-- Migración de las ediciones del agente diario (artifact -> Supabase).
-- Generada una sola vez; volver a correrla es inofensivo (on conflict do update).

on conflict (fecha) do update set
  generada = excluded.generada,
  panorama = excluded.panorama,
  escenario = excluded.escenario,
  items = excluded.items,
  escenarios_acciones = excluded.escenarios_acciones,
  fuentes = excluded.fuentes;
