insert into public.ediciones (fecha, generada, panorama, escenario, items, escenarios_acciones, fuentes) values
  ('2026-11-12', '2026-11-12T10:50:00-03:00', 'El riesgo país se duplicó desde julio y oscila entre 850 y 940 puntos: el mercado duda de que Argentina pueda refinanciar los vencimientos de 2027 y 2028 sin un apoyo externo claro. A eso se suma afuera una inflación de Estados Unidos más alta de lo esperado, que deja casi segura una suba de tasas de la Fed en diciembre y encarece el crédito para emergentes. El dato a mirar hoy es la inflación de octubre del INDEC, esperada en torno a 1,8% mensual.', '{"explicacion": "Suma moderada de los titulares sin contarlos dos veces: presión local fuerte y algo de viento en contra global", "factorAR": -0.6, "factorGlobal": -0.2}'::jsonb, '[{"ajustes": {}, "ambito": "Argentina", "canal": "Un riesgo país alto baja el precio de los soberanos y arrastra a ONs y acciones locales; si se traslada al dólar, también pierden los pesos.", "confianza": "media", "factorAR": -0.4, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "semanas", "id": "riesgo-pais", "resumen": "Pasó de 403 puntos en julio a más de 900 a comienzos de noviembre; el martes cerró en 852 tras un rebote. Los precios implican una probabilidad de reelección del Gobierno de 45%.", "titulo": "El riesgo país supera los 900 puntos y los bonos caen 20% desde sus máximos", "url": "https://www.infobae.com/economia/2026/11/08/el-gobierno-busca-encapsular-la-suba-del-riesgo-pais-para-evitar-un-impacto-en-el-dolar-y-la-actividad/"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. presionan a las acciones (tus CEDEARs) y encarecen el financiamiento de países como Argentina.", "confianza": "alta", "factorAR": -0.15, "factorGlobal": -0.4, "fuente": "Infobae", "horizonte": "semanas", "id": "fed-diciembre", "resumen": "Las tasas están en 3,75%-4% y la próxima reunión es el 9 de diciembre; el bono a dos años subió a 4,736%, su mayor alza diaria desde abril de 2025.", "titulo": "La inflación de EE.UU. sube 0,4% en octubre y el mercado da por hecha una suba de la Fed en diciembre", "url": "https://www.infobae.com/estados-unidos/2026/11/10/wall-street-cerro-en-rojo-tras-el-dato-de-inflacion-en-estados-unidos-que-reforzo-las-expectativas-de-una-suba-de-tasas/"}, {"ajustes": {"pesos": -0.04}, "ambito": "Argentina", "canal": "Menos compras de reservas aumentan la presión sobre el dólar: el rubro en pesos es el más expuesto a una corrección del tipo de cambio.", "confianza": "media", "factorAR": -0.2, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "semanas", "id": "reservas-bcra", "resumen": "Con un pago al FMI de USD 877 millones y la brecha con el contado con liquidación cerca de 9%-10%, el tipo de cambio oficial marcó récords nominales.", "titulo": "El BCRA suspendió sus compras de dólares y las reservas rondan USD 50.300 millones", "url": "https://www.infobae.com/economia/2026/11/03/riesgo-pais-arriba-de-800-puntos-y-activos-en-baja-por-que-las-acciones-y-los-bonos-argentinos-tocaron-minimos-en-un-ano/"}, {"ajustes": {}, "ambito": "Mundo", "canal": "El mercado descuenta menos ayuda externa, lo que golpea sobre todo a bonos soberanos y acciones locales.", "confianza": "baja", "factorAR": -0.25, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "meses", "id": "elecciones-region", "resumen": "Los inversores leen menos respaldo político externo para el programa económico y dudan de un nuevo apoyo del Tesoro estadounidense.", "titulo": "La reelección de Lula y la derrota republicana en EE.UU. pesan sobre los activos argentinos", "url": "https://www.infobae.com/economia/2026/11/08/el-gobierno-busca-encapsular-la-suba-del-riesgo-pais-para-evitar-un-impacto-en-el-dolar-y-la-actividad/"}, {"ajustes": {"merval": -0.02}, "ambito": "Mundo", "canal": "Menos tensión ayuda a las bolsas globales, pero un petróleo más barato le quita algo de atractivo a las energéticas argentinas del Merval.", "confianza": "media", "factorAR": 0, "factorGlobal": 0.25, "fuente": "Infobae", "horizonte": "días", "id": "petroleo-iran", "resumen": "Trump relativizó una acción militar contra Irán y se prevén conversaciones entre Rusia y Ucrania; baja la tensión geopolítica.", "titulo": "El Brent baja de USD 90 por primera vez desde agosto tras declaraciones de Trump sobre Irán", "url": "https://www.infobae.com/economia/2026/11/10/los-bonos-argentinos-operan-con-una-leve-suba-y-el-riesgo-pais-vuelve-a-ceder/"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Un dato por debajo de lo esperado sostiene la confianza en el programa; uno por encima afecta sobre todo a pesos y bonos CER.", "confianza": "baja", "factorAR": 0, "factorGlobal": 0, "fuente": "The Rio Times", "horizonte": "días", "id": "inflacion-indec", "resumen": "El INDEC publica el dato el 12 de noviembre. Las estimaciones privadas lo ubican apenas debajo de 2% para octubre y noviembre.", "titulo": "Hoy se conoce la inflación de octubre: el consenso espera 1,8% mensual", "url": "https://riotimesonline.com/argentina-markets-merval-peso-wednesday-november-11-2026"}]'::jsonb, '[{"descripcion": "El riesgo país sigue entre 850 y 950 puntos, la Fed sube 0,25 el 9 de diciembre y el dólar oficial se desliza con la brecha cerca de 10%.", "dolar": 4, "id": "base", "nombre": "Sigue la tensión", "petroleo": 0, "prob": 35, "riesgoPais": 50, "senales": ["Riesgo país entre 850 y 950", "Inflación de octubre del INDEC cerca de 1,8%"], "spx": -2, "tasas": 25}, {"descripcion": "Aparece financiamiento para los vencimientos de 2027 y 2028 o el BCRA vuelve a comprar dólares, y el riesgo país baja hacia 650.", "dolar": 2, "id": "calma", "nombre": "Se calma el riesgo país", "petroleo": -5, "prob": 25, "riesgoPais": -200, "senales": ["El BCRA vuelve a comprar dólares", "Acuerdo de financiamiento o recompra de deuda"], "spx": 3, "tasas": 25}, {"descripcion": "Sin compras del BCRA, con reservas cerca de USD 50.000 millones y la brecha en aumento, el Gobierno corrige el tipo de cambio de golpe.", "dolar": 15, "id": "salto", "nombre": "Salto cambiario", "petroleo": 0, "prob": 15, "riesgoPais": 250, "senales": ["Brecha con el CCL por encima de 15%", "Reservas cayendo varias semanas seguidas"], "spx": -2, "tasas": 25}, {"descripcion": "La inflación de EE.UU. sigue en 0,4% mensual, la Fed sube 0,50 en diciembre y anticipa más subas; caen las tecnológicas y los emergentes.", "dolar": 5, "id": "fed", "nombre": "Fed más dura", "petroleo": -5, "prob": 15, "riesgoPais": 100, "senales": ["Inflación de EE.UU. de noviembre de 0,4% o más", "Bono a 2 años arriba de 5%"], "spx": -8, "tasas": 60}, {"descripcion": "Se reaviva el conflicto con Irán tras la baja del Brent a menos de USD 90, y el petróleo vuelve a superar los USD 105.", "dolar": 3, "id": "iran", "nombre": "Vuelve la tensión con Irán", "petroleo": 20, "prob": 10, "riesgoPais": 50, "senales": ["Brent arriba de USD 100", "Amenazas sobre el estrecho de Ormuz"], "spx": -5, "tasas": 15}]'::jsonb, '[{"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/08/el-gobierno-busca-encapsular-la-suba-del-riesgo-pais-para-evitar-un-impacto-en-el-dolar-y-la-actividad/"}, {"portal": "Infobae", "url": "https://www.infobae.com/estados-unidos/2026/11/10/wall-street-cerro-en-rojo-tras-el-dato-de-inflacion-en-estados-unidos-que-reforzo-las-expectativas-de-una-suba-de-tasas/"}, {"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/03/riesgo-pais-arriba-de-800-puntos-y-activos-en-baja-por-que-las-acciones-y-los-bonos-argentinos-tocaron-minimos-en-un-ano/"}, {"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/10/los-bonos-argentinos-operan-con-una-leve-suba-y-el-riesgo-pais-vuelve-a-ceder/"}, {"portal": "The Rio Times", "url": "https://riotimesonline.com/argentina-markets-merval-peso-wednesday-november-11-2026"}]'::jsonb),
  ('2026-11-13', '2026-11-13T08:45:00-03:00', 'Los bonos argentinos tuvieron un buen día y el riesgo país bajó a 829 puntos, aunque las acciones cayeron por quinta vez seguida y la inflación de octubre dio 2,2%, más de lo esperado. Afuera el clima está más pesado: en Estados Unidos se da casi por hecha una suba de tasas en diciembre, Nvidia perdió a su CEO y el petróleo volvió a subir por ataques en Arabia Saudita. Hoy el dato a mirar es si el riesgo país se sostiene por debajo de 830 puntos mientras el mercado digiere la inflación local.', '{"explicacion": "En lo local pesa más el rebote de los bonos, el respaldo del FMI y las compras del BCRA que la inflación alta y la debilidad del real, así que el saldo argentino queda levemente positivo. En lo global, la suba de tasas que espera la Fed es el factor dominante; Nvidia y el petróleo suman presión pero se superponen con el mismo clima de aversión al riesgo, por eso no se suman enteros.", "factorAR": 0.1, "factorGlobal": -0.35}'::jsonb, '[{"ajustes": {"merval": -0.05, "soberanos": 0.05}, "ambito": "Argentina", "canal": "Mejora directa del precio de los soberanos y, si se sostiene, de las obligaciones negociables; las acciones todavía no acompañan.", "confianza": "media", "factorAR": 0.2, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "días", "id": "riesgo-pais-829", "resumen": "El jueves 12 los bonos en dólares subieron y el riesgo país bajó a 829 puntos, lejos de los 939 de la semana pasada. El MSCI Merval cayó 1% en pesos y los ADRs bajaron hasta 4%; el mayorista cerró en $1.545,5.", "titulo": "El riesgo país cae a 829 puntos con bonos en alza, pero el Merval suma cinco bajas seguidas", "url": "https://www.ambito.com/finanzas/dolar-hoy-y-dolar-blue-hoy-minuto-minuto-cuanto-opera-este-jueves-12-noviembre-n6344289"}, {"ajustes": {"cer": 0.05, "pesos": -0.03}, "ambito": "Argentina", "canal": "Favorece a los bonos CER frente a las colocaciones a tasa fija en pesos y complica la baja de tasas.", "confianza": "alta", "factorAR": -0.15, "factorGlobal": 0, "fuente": "Rankia Argentina", "horizonte": "semanas", "id": "inflacion-octubre-22", "resumen": "El INDEC informó 2,2% mensual, el dato más alto desde abril, con 33,1% interanual y 26,3% acumulado. Los estacionales subieron 5,5% y los regulados 2,9%, mientras la núcleo bajó de 1,7% a 1,5%.", "titulo": "La inflación de octubre fue 2,2%, por encima del 1,8% del REM; la núcleo bajó a 1,5%", "url": "https://www.rankia.com.ar/noticias/bolsa/7550399-inflacion-octubre-2026-ipc-indec-fue-2-mas-alto-abril"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Más compras sostienen la capacidad de pago y bajan el riesgo de un salto cambiario; el CCL en alza muestra demanda de cobertura.", "confianza": "media", "factorAR": 0.1, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "bcra-compras-reservas", "resumen": "Las compras de noviembre suman US$183 millones y las del año US$16.151 millones, pero las reservas brutas cayeron US$257 millones a US$49.073 millones por la baja del oro. El MEP cerró en $1.584,20 y el CCL subió 1,21% a $1.686,31.", "titulo": "El BCRA compró US$103 millones, la mayor compra en casi un mes, pero las reservas bajaron por el oro", "url": "https://www.ambito.com/finanzas/el-bcra-realizo-la-mayor-compra-casi-un-mes-aunque-las-reservas-cayeron-arrastradas-el-oro-n6344627"}, {"ajustes": {"soberanos": 0.03}, "ambito": "Argentina", "canal": "Un desembolso aprobado suma reservas y reduce la duda sobre los vencimientos de 2027, lo que ayuda a soberanos y ONs.", "confianza": "media", "factorAR": 0.15, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "fmi-desembolso-900", "resumen": "La vocera Julie Kozack dijo que los riesgos de refinanciación se están mitigando y atribuyó parte de la suba del riesgo país a factores globales. El directorio trataría la tercera revisión a comienzos de diciembre, sin fecha confirmada.", "titulo": "El FMI respaldó el programa y espera tratar en diciembre un desembolso de unos US$900 millones", "url": "https://www.ambito.com/economia/el-fmi-destaco-que-se-estan-mitigando-los-riesgos-refinanciacion-n6344495"}, {"ajustes": {"merval": -0.03}, "ambito": "Mundo", "canal": "Un real más barato quita competitividad a Argentina y, según Ámbito, ya redujo el excedente de dólares que compra el BCRA.", "confianza": "media", "factorAR": -0.1, "factorGlobal": -0.05, "fuente": "The Rio Times", "horizonte": "semanas", "id": "brasil-real-debil", "resumen": "El Ibovespa rebotó 2,2% a 172.236 puntos el 9 de noviembre, pero sigue 16% abajo del 23 de octubre; el dólar está cerca de R$5,50 y el tablero del 12 de noviembre lo mostraba en R$5,64. Lula no anunció medidas fiscales concretas.", "titulo": "Brasil: el real sigue débil tras el balotaje y la bolsa está 16% debajo del nivel preelectoral", "url": "https://www.riotimesonline.com/brazil-stocks-rebound-real-weak-nov-9/"}, {"ajustes": {"ons": -0.02}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. presionan a las bolsas y a los bonos emergentes, incluidos los argentinos.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.3, "fuente": "ActionForex", "horizonte": "semanas", "id": "fed-suba-diciembre", "resumen": "El IPC de octubre subió 0,4% y la núcleo 0,3%, ambos sobre lo esperado; los futuros asignan 88,7% a una suba de 0,25 puntos y 11,3% a una de 0,50. La tasa a 2 años subió unos 12 pb a 4,68%.", "titulo": "Inflación núcleo de EE.UU. en 0,3% y el mercado da por segura una suba de la Fed en diciembre", "url": "https://www.actionforex.com/action-insight/market-overview/660473-dollar-rebounds-as-fed-wallers-hawkish-warning-and-hot-cpi-lift-fed-rate-expectations/"}, {"ajustes": {"cedears": -0.05}, "ambito": "Mundo", "canal": "Pega en los CEDEARs tecnológicos y en el ánimo de las bolsas globales por el peso de Nvidia en los índices.", "confianza": "media", "factorAR": 0, "factorGlobal": -0.2, "fuente": "Eurasia Business News", "horizonte": "días", "id": "nvidia-huang-renuncia", "resumen": "Nvidia cerró en US$166,19 (-4,34%) tras llegar a caer 14%; Colette Kress asumió como CEO interina. El S&P 500 bajó 0,35% a 7.592,40 y el Nasdaq 0,39%.", "titulo": "Jensen Huang renunció a Nvidia; la acción cayó 4,3% y el S&P 500 cerró en baja", "url": "https://eurasiabusinessnews.com/2026/11/13/stock-market-today-november-12-2026-dow-sp-500-and-nasdaq-fall-after-jensen-huang-resigns/"}, {"ajustes": {"merval": 0.03}, "ambito": "Mundo", "canal": "Encarece la energía y empuja la inflación global, pero mejora a las energéticas argentinas exportadoras de Vaca Muerta.", "confianza": "baja", "factorAR": 0.05, "factorGlobal": -0.1, "fuente": "Eurasia Business News", "horizonte": "días", "id": "petroleo-ataques-arabia", "resumen": "Brent cerró en US$95,82 (+3,3%) y el WTI en US$88,74 (+2,6%) por ataques en Arabia Saudita y problemas en Ormuz, después de haber caído fuerte la semana anterior por esperanzas de paz con Irán.", "titulo": "El Brent sube 3,3% a US$95,82 por nuevos ataques a infraestructura energética saudí", "url": "https://eurasiabusinessnews.com/2026/11/13/stock-market-today-november-12-2026-dow-sp-500-and-nasdaq-fall-after-jensen-huang-resigns/"}]'::jsonb, '[{"descripcion": "El riesgo país se mueve entre 780 y 850 puntos, la Fed sube 0,25 en diciembre como se espera y el mayorista acompaña la inflación desde $1.545. Las acciones locales se estabilizan sin repuntar fuerte.", "dolar": 2, "id": "calma-tensa", "nombre": "Calma tensa", "petroleo": 0, "prob": 40, "riesgoPais": -30, "senales": ["Riesgo país sostenido debajo de 850 puntos durante la semana", "Probabilidad de suba de 0,25 de la Fed estable cerca de 90%"], "spx": 1, "tasas": 15}, {"descripcion": "El directorio del FMI aprueba los cerca de US$900 millones y el BCRA acelera compras sobre los US$16.151 millones del año, llevando el riesgo país hacia 700 puntos. Ayuda una baja del petróleo por avances con Irán.", "dolar": 1, "id": "alivio-fmi-reservas", "nombre": "Alivio por FMI y reservas", "petroleo": -5, "prob": 20, "riesgoPais": -120, "senales": ["Fecha confirmada del directorio del FMI a comienzos de diciembre", "Compras diarias del BCRA por encima de US$100 millones y reservas de nuevo sobre US$50.000 millones"], "spx": 2, "tasas": 0}, {"descripcion": "Más funcionarios apoyan una suba de 0,50 en diciembre y más subas en 2027, con la tasa a 2 años sobre 4,68%. Las bolsas corrigen y los emergentes pierden atractivo.", "dolar": 3, "id": "fed-agresiva", "nombre": "Fed más agresiva", "petroleo": 0, "prob": 15, "riesgoPais": 60, "senales": ["Probabilidad de suba de 0,50 en diciembre por encima de 30%", "S&P 500 por debajo de 7.400 puntos"], "spx": -6, "tasas": 40}, {"descripcion": "La inflación no baja del 2% en noviembre, el BCRA frena las compras y el real sigue cayendo, devolviendo el riesgo país a la zona de 950-1.000 puntos. El CCL, hoy en $1.686, se aleja del oficial.", "dolar": 8, "id": "estres-local", "nombre": "Estrés local", "petroleo": 5, "prob": 15, "riesgoPais": 150, "senales": ["Brecha CCL-mayorista por encima de 12%", "Riesgo país de nuevo sobre 900 puntos"], "spx": -2, "tasas": 15}, {"descripcion": "Los ataques en Arabia Saudita y Ormuz escalan y el Brent vuelve sobre US$110 desde US$95,82, reavivando la inflación global. Las energéticas argentinas resisten pero el resto del mercado sufre.", "dolar": 3, "id": "shock-petrolero", "nombre": "Shock petrolero", "petroleo": 20, "prob": 10, "riesgoPais": 40, "senales": ["Brent cerrando por encima de US$105", "Nuevo cierre del oleoducto Este-Oeste saudí o de tránsito en Ormuz"], "spx": -4, "tasas": 25}]'::jsonb, '[{"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/dolar-hoy-y-dolar-blue-hoy-minuto-minuto-cuanto-opera-este-jueves-12-noviembre-n6344289"}, {"portal": "Rankia Argentina", "url": "https://www.rankia.com.ar/noticias/bolsa/7550399-inflacion-octubre-2026-ipc-indec-fue-2-mas-alto-abril"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/el-bcra-realizo-la-mayor-compra-casi-un-mes-aunque-las-reservas-cayeron-arrastradas-el-oro-n6344627"}, {"portal": "Ámbito", "url": "https://www.ambito.com/economia/el-fmi-destaco-que-se-estan-mitigando-los-riesgos-refinanciacion-n6344495"}, {"portal": "The Rio Times", "url": "https://www.riotimesonline.com/brazil-stocks-rebound-real-weak-nov-9/"}, {"portal": "ActionForex", "url": "https://www.actionforex.com/action-insight/market-overview/660473-dollar-rebounds-as-fed-wallers-hawkish-warning-and-hot-cpi-lift-fed-rate-expectations/"}, {"portal": "Eurasia Business News", "url": "https://eurasiabusinessnews.com/2026/11/13/stock-market-today-november-12-2026-dow-sp-500-and-nasdaq-fall-after-jensen-huang-resigns/"}]'::jsonb),
  ('2026-11-14', '2026-11-14T08:35:30-03:00', 'La semana cerró con alivio en los bonos: el riesgo país bajó 107 puntos y quedó en 830, aunque sigue lejos de los 600 de mediados de octubre y la inflación de octubre (2,2%) salió peor de lo esperado. Afuera el clima se puso más pesado: la tasa a 10 años de EE.UU. está en 5,15% y el mercado da casi por hecha una suba de la Fed en diciembre, mientras Wall Street digiere la salida del CEO de Nvidia. El dato a mirar hoy y el lunes es si el riesgo país sostiene los 830 puntos con la tasa estadounidense arriba del 5%.', '{"explicacion": "Lo local queda levemente negativo: el rebote de bonos de la semana y el respaldo del FMI compensan solo en parte la inflación más alta, la tasa del 17% del Bonar 2029 y el dólar firme. Lo global pesa más: las tasas de EE.UU. arriba de 5% con suba de la Fed casi descontada y el golpe a las tecnológicas son el mismo shock de condiciones financieras, así que no se suman dos veces.", "factorAR": -0.1, "factorGlobal": -0.3}'::jsonb, '[{"ajustes": {"cer": 0.05, "pesos": -0.03}, "ambito": "Argentina", "canal": "Pone en duda la desinflación y presiona las tasas en pesos, aunque los bonos CER ajustan su capital con este dato.", "confianza": "alta", "factorAR": -0.15, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "semanas", "id": "inflacion-octubre-22", "resumen": "El IPC subió 2,2% en octubre contra 1,8% que esperaba el REM; acumula 26,3% en el año y 33,1% interanual. La núcleo fue 1,5%, empujada la general por gas (regulados +2,9%) y verduras (estacionales +5,5%).", "titulo": "La inflación de octubre fue 2,2%, la más alta desde abril y arriba de lo esperado", "url": "https://www.infobae.com/economia/2026/11/12/la-inflacion-en-octubre-fue-de-22-y-acumulo-331-en-los-ultimos-doce-meses/"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Una tregua en los bonos soberanos mejora el precio de Globales y Bonares y le da aire a acciones y ONs.", "confianza": "media", "factorAR": 0.25, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "días", "id": "riesgo-pais-830", "resumen": "Tras el pico de 939 puntos del 6 de noviembre, el riesgo país cortó un mes de subas y terminó el viernes en 830; el MSCI Merval subió 1% en dólares en la semana y los ADR treparon hasta 9% el viernes.", "titulo": "El riesgo país bajó 107 puntos en la semana y cerró en 830", "url": "https://www.ambito.com/finanzas/dolar-hoy-y-dolar-blue-hoy-minuto-minuto-cuanto-opera-este-viernes-13-noviembre-n6344766"}, {"ajustes": {"soberanos": -0.03}, "ambito": "Argentina", "canal": "Si el Tesoro no puede refinanciarse en dólares, depende de reservas y swaps, lo que mantiene alto el riesgo país.", "confianza": "media", "factorAR": -0.3, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "meses", "id": "bonar-2029-tasa-17", "resumen": "El AO29 cotiza cerca de u$s77 con una TIR de 17% y cayó 23% en cuatro meses; Economía dejó de ofrecerlo y no pudo colocar unos u$s800 millones este año. El programa 2027 contaba con u$s5.000 millones del mercado local.", "titulo": "El Bonar 2029 rinde 17% y complica el plan de conseguir u$s5.000 millones en 2027", "url": "https://www.ambito.com/finanzas/con-el-riesgo-pais-arriba-800-puntos-la-tasa-del-bonar-2029-salto-al-17-y-complica-el-programa-financiero-2027-n6344622"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Un aval del Fondo y más reservas reducen el riesgo de pago y sostienen a bonos y al peso.", "confianza": "media", "factorAR": 0.15, "factorGlobal": 0, "fuente": "Perfil", "horizonte": "semanas", "id": "fmi-respaldo-900", "resumen": "La vocera Julie Kozack reconoció factores domésticos en la suba del riesgo país pero destacó los fundamentos; el desembolso de unos US$900 millones se trataría en diciembre, sin fecha confirmada. El BCRA lleva compras por US$16.151 millones en 2026 y reservas brutas de US$49.073 millones.", "titulo": "El FMI pidió no sobrerreaccionar y confirmó que la revisión de US$900 millones irá al Directorio", "url": "https://www.perfil.com/economia/el-fmi-reconocio-factores-internos-en-la-volatilidad-que-disparo-el-riesgo-pais-pero-pidio-no-centrarse-en-el-corto-plazo-aVAyv6K7wRnc"}, {"ajustes": {"pesos": -0.05}, "ambito": "Argentina", "canal": "Un peso que se debilita resta a lo invertido en pesos medido en dólares, aunque el margen hasta el techo de la banda acota el riesgo inmediato.", "confianza": "media", "factorAR": -0.1, "factorGlobal": 0, "fuente": "iProfesional", "horizonte": "semanas", "id": "dolar-mayorista-5-semanas", "resumen": "El mayorista quedó a 27,1% del techo de la banda ($1.968); los futuros marcan $1.594,50 para fin de diciembre. El MEP cerró en $1.594,50 y el CCL en $1.669,98.", "titulo": "El dólar mayorista cerró en $1.544 tras cinco semanas de suba; el blue tocó máximos nominales", "url": "https://www.iprofesional.com/finanzas/469071-caen-los-bonos-el-riesgo-pais-vuelve-a-subir-y-supera-los-840-puntos-basicos"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. encarecen el financiamiento de emergentes y bajan la valuación de acciones del mundo, incluidos los Cedears.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.3, "fuente": "AP", "horizonte": "semanas", "id": "fed-suba-diciembre", "resumen": "La tasa a 10 años subió a 5,15% y la de 2 años a 4,87%; los economistas esperan una suba de la Fed en diciembre y probablemente otra en enero. El S&P 500 cerró en 7.561,67 (-0,4%), aunque ganó 2,5% en la semana.", "titulo": "Bonos del Tesoro al 5,15% y la Fed encaminada a subir tasas en diciembre", "url": "https://whdh.com/news/stocks-fall-but-wall-street-notches-a-winning-week-after-several-turbulent-days/"}, {"ajustes": {"cedears": -0.05}, "ambito": "Mundo", "canal": "Pega directo en los Cedears tecnológicos, que pesan mucho en las carteras dolarizadas.", "confianza": "media", "factorAR": 0, "factorGlobal": -0.2, "fuente": "Perfil", "horizonte": "días", "id": "nvidia-renuncia-huang", "resumen": "Jensen Huang dejó Nvidia en medio de un escándalo y la acción cayó 6% el jueves; el viernes el Nasdaq perdió 0,9% y la empresa resignó cerca de US$600.000 millones de capitalización en la semana.", "titulo": "Renunció el CEO de Nvidia y la acción arrastró a las tecnológicas de inteligencia artificial", "url": "https://www.perfil.com/economia/el-riesgo-pais-cerro-por-debajo-de-los-830-puntos-ante-el-avance-de-los-bonos-aIJJQ9e39SDr"}, {"ajustes": {"merval": 0.03}, "ambito": "Mundo", "canal": "Un petróleo alto alimenta la inflación en EE.UU. y las tasas, pero favorece a las energéticas argentinas del Merval.", "confianza": "media", "factorAR": 0.05, "factorGlobal": -0.1, "fuente": "Trading Economics", "horizonte": "semanas", "id": "brent-iran-96", "resumen": "El Brent rebotó desde un mínimo de 10 semanas de US$91,5 (10 de noviembre) y cerró el viernes en US$95,84; en febrero, antes de la guerra con Irán, rondaba US$72. La oferta del Golfo se recupera, pero las rutas siguen bajo riesgo.", "titulo": "El Brent volvió a US$96 después de que Trump dijo que EE.UU. no necesita un acuerdo con Irán", "url": "https://tradingeconomics.com/commodity/brent-crude-oil/news/600380"}]'::jsonb, '[{"descripcion": "El Directorio del FMI aprueba los US$900 millones, el BCRA sigue comprando y el riesgo país baja desde 830 hacia la zona de 680. Afuera la Fed sube 25 pb pero sin sorpresas.", "dolar": 2, "id": "alivio-fmi", "nombre": "Alivio con aval del FMI", "petroleo": -5, "prob": 25, "riesgoPais": -150, "senales": ["Riesgo país por debajo de 780 puntos", "Fecha confirmada del Directorio del FMI en diciembre"], "spx": 3, "tasas": -15}, {"descripcion": "El riesgo país oscila entre 780 y 880 mientras la tasa a 10 años de EE.UU. sigue cerca de 5,15% y la Fed sube 25 pb en diciembre. El dólar mayorista se acerca a los $1.594 que marcan los futuros.", "dolar": 3, "id": "lateral-fed-dura", "nombre": "Lateral con Fed dura", "petroleo": 0, "prob": 35, "riesgoPais": -20, "senales": ["Tasa a 10 años de EE.UU. entre 5% y 5,3%", "Mayorista entre $1.540 y $1.600"], "spx": -1, "tasas": 15}, {"descripcion": "La inflación de EE.UU. sigue alta y la Fed sube 50 pb en diciembre, con la tasa a 10 años arriba de 5,5%. Wall Street corrige desde 7.560 y los emergentes sufren salida de fondos.", "dolar": 4, "id": "fed-sube-50", "nombre": "Fed sube 50 pb", "petroleo": 0, "prob": 15, "riesgoPais": 120, "senales": ["Mercado de futuros con más de 50% de chance de suba de 50 pb", "S&P 500 por debajo de 7.200"], "spx": -8, "tasas": 50}, {"descripcion": "Sin financiamiento en dólares (Bonar 2029 al 17%) y con dudas políticas para 2027, el riesgo país vuelve arriba de 1.000 y el mayorista va hacia el techo de la banda de $1.968. La inflación sigue arriba de 2%.", "dolar": 15, "id": "estres-2027", "nombre": "Estrés local por 2027", "petroleo": 0, "prob": 15, "riesgoPais": 300, "senales": ["Riesgo país arriba de 950 puntos", "Brecha MEP-mayorista mayor a 8%"], "spx": -1, "tasas": 10}, {"descripcion": "Se cortan las negociaciones con Irán y vuelven los ataques en Ormuz; el Brent pasa de US$96 a más de US$110. Sube la inflación global y las tasas, aunque las energéticas argentinas amortiguan.", "dolar": 3, "id": "rebrote-iran", "nombre": "Rebrote en Irán", "petroleo": 20, "prob": 10, "riesgoPais": 60, "senales": ["Brent arriba de US$105", "Nuevos ataques a petroleros en el estrecho de Ormuz"], "spx": -5, "tasas": 20}]'::jsonb, '[{"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/12/la-inflacion-en-octubre-fue-de-22-y-acumulo-331-en-los-ultimos-doce-meses/"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/dolar-hoy-y-dolar-blue-hoy-minuto-minuto-cuanto-opera-este-viernes-13-noviembre-n6344766"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/con-el-riesgo-pais-arriba-800-puntos-la-tasa-del-bonar-2029-salto-al-17-y-complica-el-programa-financiero-2027-n6344622"}, {"portal": "Perfil", "url": "https://www.perfil.com/economia/el-fmi-reconocio-factores-internos-en-la-volatilidad-que-disparo-el-riesgo-pais-pero-pidio-no-centrarse-en-el-corto-plazo-aVAyv6K7wRnc"}, {"portal": "iProfesional", "url": "https://www.iprofesional.com/finanzas/469071-caen-los-bonos-el-riesgo-pais-vuelve-a-subir-y-supera-los-840-puntos-basicos"}, {"portal": "AP", "url": "https://whdh.com/news/stocks-fall-but-wall-street-notches-a-winning-week-after-several-turbulent-days/"}, {"portal": "Perfil", "url": "https://www.perfil.com/economia/el-riesgo-pais-cerro-por-debajo-de-los-830-puntos-ante-el-avance-de-los-bonos-aIJJQ9e39SDr"}, {"portal": "Trading Economics", "url": "https://tradingeconomics.com/commodity/brent-crude-oil/news/600380"}]'::jsonb),
  ('2026-11-15', '2026-11-15T09:10:00-03:00', 'Es fin de semana y los mercados no operaron: el riesgo país quedó en 830 puntos después de bajar 107 en la semana, y el dólar mayorista en $1.544. Lo nuevo es político y fiscal: Milei confirmó el sábado que va por la reelección en 2027, y el lunes Economía publica el resultado fiscal de octubre, clave para cumplir la meta con el FMI. Afuera, la semana trae el balance de Nvidia el martes 17 y la salida a bolsa de Anthropic el miércoles 18, con la tasa a 10 años de EE.UU. en 5,15%; el dato a mirar es si el riesgo país se sostiene debajo de 850.', '{"explicacion": "Lo local queda casi neutro: el rebote de bonos y el respaldo del FMI se compensan con la inflación de 2,2%, la falta de financiamiento en dólares y la incógnita fiscal del lunes; la candidatura de Milei despeja una duda pero abre la discusión por 2027. Lo global sigue pesando porque la Fed casi segura subiendo en diciembre, las tasas arriba de 5% y la volatilidad de las tecnológicas (Nvidia, Anthropic) son el mismo shock de condiciones financieras, así que se cuenta una sola vez.", "factorAR": -0.05, "factorGlobal": -0.3}'::jsonb, '[{"ajustes": {"merval": -0.03}, "ambito": "Argentina", "canal": "Mejora el precio de los bonos en dólares y, con rezago, el de acciones y ONs que siguen al riesgo soberano.", "confianza": "media", "factorAR": 0.2, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "días", "id": "riesgo-pais-830-semana", "resumen": "Pasó de 939 a 832 puntos en la semana corta; los Globales subieron 2,5% promedio, pero el MSCI Merval apenas 0,6% en pesos. IEB ve al riesgo país estabilizándose entre 700 y 900 puntos.", "titulo": "El riesgo país cortó un mes de subas: bajó 107 puntos y cerró la semana en 832", "url": "https://www.ambito.com/finanzas/las-acciones-y-los-bonos-se-someten-la-ultima-rueda-semanal-conocerse-el-dato-inflacion-n6344826"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Un dato fiscal sólido refuerza la aprobación de la revisión del FMI y la capacidad de pago; uno flojo sumaría presión sobre bonos.", "confianza": "media", "factorAR": 0.1, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "días", "id": "resultado-fiscal-octubre", "resumen": "A septiembre el superávit primario acumulado es $13,7 billones y la meta anual es $16,2 billones; falta $2,5 billones en el último trimestre, con diciembre habitualmente deficitario. El gasto primario de octubre cayó 9,7% real interanual según IARAF.", "titulo": "El lunes se conoce el resultado fiscal de octubre, clave para la meta de superávit con el FMI", "url": "https://www.ambito.com/economia/el-resultado-fiscal-octubre-definira-si-el-gobierno-logra-cumplir-la-meta-superavit-acordada-el-fmi-n6345009"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Despeja dudas sobre la continuidad del programa, pero pone el foco del mercado en el riesgo electoral de 2027, que hoy encarece la deuda.", "confianza": "baja", "factorAR": 0.05, "factorGlobal": 0, "fuente": "The Rio Times", "horizonte": "meses", "id": "milei-reeleccion-2027", "resumen": "Lo dijo el sábado 14 en la Casa Rosada y dejó de lado la condición que había puesto en agosto. En Polymarket tiene 43,5% de chances de ganar, frente a 32,5% de Kicillof; la elección general es el 24 de octubre de 2027.", "titulo": "Milei confirmó que irá por la reelección en 2027", "url": "https://www.riotimesonline.com/argentina-milei-confirms-reelection-bid/"}, {"ajustes": {"cer": 0.05, "pesos": -0.03}, "ambito": "Argentina", "canal": "Una inflación más alta presiona las tasas en pesos y favorece relativamente a los bonos CER.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "semanas", "id": "inflacion-octubre-nucleo", "resumen": "El IPC subió 2,2% (REM esperaba 1,8%) y acumula 26,3% en el año; regulados +2,9% por gas y estacionales +5,5%. La núcleo de 1,5% es la más baja desde julio de 2025, y el REM espera 1,7% en noviembre.", "titulo": "Inflación de 2,2% en octubre: la general se aceleró, pero la núcleo bajó a 1,5%", "url": "https://www.infobae.com/economia/2026/11/12/la-inflacion-en-octubre-fue-de-22-y-acumulo-331-en-los-ultimos-doce-meses/"}, {"ajustes": {"pesos": -0.05}, "ambito": "Argentina", "canal": "Un peso que se deprecia de a poco resta a lo invertido en pesos medido en dólares; el margen hasta el techo acota el riesgo inmediato.", "confianza": "media", "factorAR": -0.05, "factorGlobal": 0, "fuente": "iProfesional", "horizonte": "semanas", "id": "dolar-mayorista-1544", "resumen": "Queda a 27,1% del techo de la banda ($1.968,10). El MEP cerró en $1.594,50 y el CCL en $1.669,98; el BCRA hizo su mayor compra en casi un mes, aunque las reservas brutas bajaron por el oro.", "titulo": "El mayorista cerró en $1.544 tras cinco semanas de suba; los futuros marcan $1.594 a diciembre", "url": "https://www.iprofesional.com/finanzas/469071-caen-los-bonos-el-riesgo-pais-vuelve-a-subir-y-supera-los-840-puntos-basicos"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. encarecen el financiamiento de emergentes y bajan la valuación de las acciones del mundo, incluidos los Cedears.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.3, "fuente": "Reuters", "horizonte": "semanas", "id": "fed-suba-diciembre-waller", "resumen": "Waller apoya subir al menos 25 pb el 8-9 de diciembre (a 4,00%-4,25%) y 50 pb si la núcleo sigue en 0,3% mensual; el PCE de septiembre fue 3,7%. Al cierre del viernes el mercado daba 88% a +25 pb y 12% a +50 pb, con la tasa a 10 años en 5,15%.", "titulo": "La Fed se encamina a subir tasas en diciembre y Waller abre la puerta a 50 pb", "url": "https://www.kitco.com/news/off-the-wire/2026-11-10/feds-waller-plans-support-least-quarter-point-rate-hike-december"}, {"ajustes": {"cedears": -0.05}, "ambito": "Mundo", "canal": "Mueve directo a los Cedears tecnológicos, que pesan mucho en las carteras dolarizadas, y al apetito global por riesgo.", "confianza": "media", "factorAR": 0, "factorGlobal": -0.1, "fuente": "Investrade", "horizonte": "días", "id": "nvidia-balance-anthropic-ipo", "resumen": "Nvidia reporta el 17 tras la renuncia de Jensen Huang; el mercado espera que ratifique una suba de ventas de 70%. Anthropic fijaría precio el 18 entre US$70 y US$78 por acción (valuación de US$1,3 a 1,45 billones); el Nasdaq cayó 0,9% el viernes.", "titulo": "Semana clave para la IA: balance de Nvidia el martes y salida a bolsa de Anthropic el miércoles", "url": "https://investrade.com/market-review-november-13-2026/"}, {"ajustes": {"merval": 0.03}, "ambito": "Mundo", "canal": "Un petróleo alto alimenta la inflación y las tasas en EE.UU., pero favorece a las energéticas argentinas del Merval.", "confianza": "media", "factorAR": 0.05, "factorGlobal": -0.1, "fuente": "Trading Economics", "horizonte": "semanas", "id": "brent-96-iran", "resumen": "Rebotó desde un mínimo de 10 semanas de US$91,5 y cerró el viernes en US$95,84, tras decir Trump que EE.UU. no necesita un acuerdo con Irán. Arabia Saudita subió 26% su producción de octubre y los inventarios de EE.UU. crecieron 4,66 millones de barriles.", "titulo": "El Brent volvió a US$96 tras el giro de Trump con Irán, aunque la oferta del Golfo se recupera", "url": "https://tradingeconomics.com/commodity/brent-crude-oil/news/600509"}]'::jsonb, '[{"descripcion": "El superávit de octubre deja cerca la meta de $16,2 billones, el Directorio del FMI aprueba los US$900 millones y el riesgo país baja de 830 hacia 680. Afuera la Fed sube 25 pb sin sorpresas.", "dolar": 2, "id": "alivio-fmi-fiscal", "nombre": "Alivio con FMI y caja fiscal", "petroleo": -5, "prob": 25, "riesgoPais": -150, "senales": ["Riesgo país por debajo de 780 puntos", "Fecha confirmada del Directorio del FMI en diciembre"], "spx": 3, "tasas": -15}, {"descripcion": "El riesgo país oscila entre 780 y 880, dentro del rango 700-900 que proyecta IEB, mientras la tasa a 10 años de EE.UU. sigue cerca de 5,15% y la Fed sube 25 pb. El mayorista va hacia los $1.594 que marcan los futuros.", "dolar": 3, "id": "lateral-fed-dura", "nombre": "Lateral con Fed dura", "petroleo": 0, "prob": 35, "riesgoPais": -20, "senales": ["Tasa a 10 años de EE.UU. entre 5% y 5,3%", "Mayorista entre $1.540 y $1.600"], "spx": -1, "tasas": 15}, {"descripcion": "Nvidia decepciona, la salida de Anthropic se hace por debajo de US$70 y la inflación obliga a la Fed a subir 50 pb. El S&P 500 corrige desde 7.560 y los emergentes sufren salida de fondos.", "dolar": 4, "id": "golpe-ia-fed-50", "nombre": "Golpe tecnológico y Fed de 50 pb", "petroleo": -3, "prob": 15, "riesgoPais": 120, "senales": ["S&P 500 por debajo de 7.200", "Futuros con más de 50% de chance de suba de 50 pb"], "spx": -8, "tasas": 40}, {"descripcion": "Sin financiamiento en dólares (Bonar 2029 cerca de 17%) y con la carrera de 2027 ya abierta, el riesgo país vuelve arriba de 1.000 y el mayorista se acerca al techo de $1.968. La inflación sigue arriba de 2%.", "dolar": 15, "id": "estres-2027", "nombre": "Estrés local por 2027", "petroleo": 0, "prob": 15, "riesgoPais": 300, "senales": ["Riesgo país arriba de 950 puntos", "Brecha CCL-mayorista mayor a 12%"], "spx": -1, "tasas": 10}, {"descripcion": "Se cortan los contactos con Irán y vuelven los ataques en Ormuz; el Brent pasa de US$96 a más de US$110. Sube la inflación global, aunque las energéticas argentinas amortiguan.", "dolar": 3, "id": "rebrote-iran", "nombre": "Rebrote en Irán", "petroleo": 20, "prob": 10, "riesgoPais": 60, "senales": ["Brent arriba de US$105", "Nuevos ataques a petroleros en el estrecho de Ormuz"], "spx": -5, "tasas": 20}]'::jsonb, '[{"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/las-acciones-y-los-bonos-se-someten-la-ultima-rueda-semanal-conocerse-el-dato-inflacion-n6344826"}, {"portal": "Ámbito", "url": "https://www.ambito.com/economia/el-resultado-fiscal-octubre-definira-si-el-gobierno-logra-cumplir-la-meta-superavit-acordada-el-fmi-n6345009"}, {"portal": "The Rio Times", "url": "https://www.riotimesonline.com/argentina-milei-confirms-reelection-bid/"}, {"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/12/la-inflacion-en-octubre-fue-de-22-y-acumulo-331-en-los-ultimos-doce-meses/"}, {"portal": "iProfesional", "url": "https://www.iprofesional.com/finanzas/469071-caen-los-bonos-el-riesgo-pais-vuelve-a-subir-y-supera-los-840-puntos-basicos"}, {"portal": "Reuters", "url": "https://www.kitco.com/news/off-the-wire/2026-11-10/feds-waller-plans-support-least-quarter-point-rate-hike-december"}, {"portal": "Investrade", "url": "https://investrade.com/market-review-november-13-2026/"}, {"portal": "Trading Economics", "url": "https://tradingeconomics.com/commodity/brent-crude-oil/news/600509"}]'::jsonb),
  ('2026-11-16', '2026-11-16T08:50:00-03:00', 'Los bonos argentinos rebotaron 3% la semana pasada y el riesgo país bajó 109 puntos hasta 830, pero la inflación de octubre (2,2%) salió más alta de lo esperado y las acciones siguen cerca de sus mínimos del año. Afuera, la inflación de EE.UU. empuja a la Fed hacia una suba de tasas en diciembre y la renuncia del CEO de Nvidia sacudió a las tecnológicas, mientras el petróleo bajó por señales de calma con Irán. Hoy el dato a mirar es si el riesgo país se sostiene por debajo de 830 puntos y si el BCRA sigue comprando dólares.', '{"explicacion": "El rebote de los bonos ya está en precios; lo nuevo pesa algo hacia abajo en lo local (inflación más alta, peso atrasado y Brasil débil) y en lo global (Fed más dura con el bono a 10 años en 5,15% y dudas sobre la IA), compensado en parte por el petróleo más barato. Se cuenta una sola vez el efecto de las tasas de EE.UU. sobre el riesgo país.", "factorAR": -0.1, "factorGlobal": -0.2}'::jsonb, '[{"ajustes": {"soberanos": 0.03}, "ambito": "Argentina", "canal": "Una baja sostenida del riesgo país sube el precio de soberanos y ONs y mejora la perspectiva de refinanciar los vencimientos de 2027.", "confianza": "media", "factorAR": 0.25, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "semanas", "id": "riesgo-pais-baja-109-pb", "resumen": "Bonares y Globales subieron 3% en promedio y el riesgo país cerró en 830 pb, tras tocar 939 pb la semana anterior; el Merval subió 0,7% en la semana y aún pierde 26% en dólares en 2026.", "titulo": "Los bonos rebotaron 3% y el riesgo país bajó 109 puntos en la semana, a 830", "url": "https://www.infobae.com/economia/2026/11/14/los-bonos-rebotaron-3-y-el-riesgo-pais-argentino-desconto-mas-de-100-puntos-basicos-en-una-semana-de-alta-volatilidad-externa/"}, {"ajustes": {"cer": 0.05, "pesos": -0.05}, "ambito": "Argentina", "canal": "Más inflación favorece a los bonos CER frente a las tasas fijas en pesos y complica la desinflación prometida antes de 2027.", "confianza": "alta", "factorAR": -0.15, "factorGlobal": 0, "fuente": "Perfil", "horizonte": "semanas", "id": "inflacion-octubre-2-2", "resumen": "El IPC subió 2,2% en octubre (33,1% interanual, 26,3% en el año), el mayor registro desde abril y por encima del 1,8% del REM; la núcleo bajó a 1,5% según Puente.", "titulo": "La inflación de octubre fue 2,2%, por encima del 1,8% que esperaba el mercado", "url": "https://www.perfil.com/economia/tras-el-duro-dato-inflacionario-el-riesgo-pais-cerro-la-semana-al-alza-a8ViV4Q7dJlH"}, {"ajustes": {"mep": 0.03, "pesos": -0.03}, "ambito": "Argentina", "canal": "Las compras sostienen reservas, pero una brecha creciente y un peso atrasado elevan el riesgo de un salto cambiario que golpea a quien está en pesos.", "confianza": "media", "factorAR": -0.05, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "meses", "id": "brecha-y-compras-bcra", "resumen": "El mayorista cerró en $1.548,50, 27,5% debajo del techo de la banda; el CCL quedó en $1.677,53 y el BCRA acumula compras por USD 16.151 millones en 2026, mientras el tipo de cambio real cayó 5,1% desde julio según PPI.", "titulo": "El BCRA compra dólares pero el peso se atrasa: brecha con el CCL de 8,3%", "url": "https://www.ambito.com/finanzas/dolar-el-mercado-pone-la-lupa-la-brecha-cambiaria-la-suba-del-blue-y-la-baja-del-oficial-n6345542"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas de EE.UU. más altas encarecen el financiamiento de emergentes y presionan a bolsas y CEDEARs.", "confianza": "media", "factorAR": -0.1, "factorGlobal": -0.3, "fuente": "TheStreet Pro", "horizonte": "semanas", "id": "fed-subas-goldman", "resumen": "La inflación núcleo de EE.UU. subió 0,30% en octubre; Goldman espera +25 pb el 8-9 de diciembre y otra en marzo (techo 4,25%-4,5%), y los futuros ya descuentan unos 63 pb de subas hasta fines de 2027.", "titulo": "Tras otro IPC caliente, Goldman suma una suba de la Fed en marzo de 2027", "url": "https://pro.thestreet.com/stock-market-today/goldman-now-calls-for-two-more-hikes-pushes-first-cut-to-december-2027"}, {"ajustes": {"cedears": -0.05}, "ambito": "Mundo", "canal": "La caída de las tecnológicas pesa directo sobre los CEDEARs, que concentran Nvidia y otras grandes de IA.", "confianza": "media", "factorAR": -0.05, "factorGlobal": -0.15, "fuente": "AP", "horizonte": "días", "id": "nvidia-ceo-renuncia", "resumen": "El viernes el S&P 500 cayó 0,4% a 7.561,67 y el Nasdaq 0,9% por la salida de Jensen Huang, aunque la semana cerró con +2,5%; el bono a 10 años subió a 5,15%.", "titulo": "Renunció el CEO de Nvidia; el S&P 500 igual ganó 2,5% en la semana", "url": "https://krmg.com/2026/11/13/how-major-us-stock-indexes-fared-friday-11-13-2026/"}, {"ajustes": {"merval": -0.03, "ons": -0.02}, "ambito": "Mundo", "canal": "Un petróleo más barato alivia la inflación mundial pero resta a YPF, Vaca Muerta y al superávit energético argentino.", "confianza": "media", "factorAR": -0.05, "factorGlobal": 0.1, "fuente": "The Nation (Reuters)", "horizonte": "semanas", "id": "petroleo-baja-iran", "resumen": "El Brent cerró en US$92,57 el 9 de noviembre tras perder 16% la semana previa; JPMorgan estima un excedente global de 1,4 millones de barriles diarios y el viernes terminó cerca de US$96.", "titulo": "El Brent cae a mínimos desde agosto por señales de calma con Irán y exceso de oferta", "url": "https://www.nationthailand.com/news/world/40073309"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Un real débil abarata a Brasil frente a Argentina y suma presión sobre el tipo de cambio y las exportaciones locales.", "confianza": "media", "factorAR": -0.1, "factorGlobal": -0.05, "fuente": "The Rio Times", "horizonte": "meses", "id": "brasil-real-debil", "resumen": "El dólar cotiza cerca de R$5,50-5,64 (11% más que el 23 de octubre) y Lula habló de deuda y tasas sin anunciar recortes; el Ibovespa quedó 16% debajo de los 205.083 puntos previos al balotaje.", "titulo": "Brasil: el real sigue débil y el Ibovespa está 16% abajo de su nivel previo al balotaje", "url": "https://www.riotimesonline.com/?p=786167"}]'::jsonb, '[{"descripcion": "El riesgo país se estabiliza entre 780 y 850 pb y el mayorista sigue cerca de $1.550, mientras la Fed sube 25 pb en diciembre como se espera.", "dolar": 2, "id": "calma-tasas-altas", "nombre": "Calma con tasas altas", "petroleo": -3, "prob": 35, "riesgoPais": -30, "senales": ["El BCRA sigue comprando más de USD 30 millones por día", "El bono a 10 años de EE.UU. se mantiene entre 5% y 5,2%"], "spx": 1, "tasas": 15}, {"descripcion": "El rebote de los bonos continúa y el riesgo país vuelve hacia 700 pb, ayudado por un dato de inflación de noviembre más bajo y un mundo más tranquilo.", "dolar": 1, "id": "compresion-riesgo", "nombre": "Compresión de riesgo", "petroleo": -5, "prob": 20, "riesgoPais": -150, "senales": ["Riesgo país por debajo de 780 pb", "Inflación de noviembre bajo 2% en mediciones privadas"], "spx": 4, "tasas": -10}, {"descripcion": "La Fed sube 50 pb o anticipa más subas y la crisis de Nvidia se contagia al resto de las tecnológicas, con el S&P 500 lejos de sus 7.561 puntos actuales.", "dolar": 3, "id": "fed-dura-ia", "nombre": "Fed dura y caída de la IA", "petroleo": -5, "prob": 20, "riesgoPais": 100, "senales": ["Futuros con más de 50% de chance de suba de 50 pb en diciembre", "Nueva caída de más de 5% del índice de semiconductores"], "spx": -8, "tasas": 40}, {"descripcion": "La brecha con el CCL (8,3%) se amplía, el riesgo país vuelve sobre 950 pb y el mercado duda del financiamiento de los vencimientos de 2027; el oficial se acerca al techo de la banda ($1.968).", "dolar": 12, "id": "estres-cambiario-local", "nombre": "Estrés cambiario y deuda 2027", "petroleo": 0, "prob": 15, "riesgoPais": 200, "senales": ["CCL por encima de $1.750 y brecha mayor a 12%", "El BCRA deja de comprar o vende dólares varios días seguidos"], "spx": 0, "tasas": 10}, {"descripcion": "Fracasan las negociaciones con Irán y vuelven los ataques a buques en Ormuz, llevando el Brent desde la zona de US$96 a más de US$110.", "dolar": 3, "id": "rebrote-iran", "nombre": "Rebrote en Medio Oriente", "petroleo": 20, "prob": 10, "riesgoPais": 60, "senales": ["Brent por encima de US$105", "Nuevos ataques a petroleros o a instalaciones de Aramco"], "spx": -4, "tasas": 20}]'::jsonb, '[{"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/14/los-bonos-rebotaron-3-y-el-riesgo-pais-argentino-desconto-mas-de-100-puntos-basicos-en-una-semana-de-alta-volatilidad-externa/"}, {"portal": "Perfil", "url": "https://www.perfil.com/economia/tras-el-duro-dato-inflacionario-el-riesgo-pais-cerro-la-semana-al-alza-a8ViV4Q7dJlH"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/dolar-el-mercado-pone-la-lupa-la-brecha-cambiaria-la-suba-del-blue-y-la-baja-del-oficial-n6345542"}, {"portal": "TheStreet Pro", "url": "https://pro.thestreet.com/stock-market-today/goldman-now-calls-for-two-more-hikes-pushes-first-cut-to-december-2027"}, {"portal": "AP", "url": "https://krmg.com/2026/11/13/how-major-us-stock-indexes-fared-friday-11-13-2026/"}, {"portal": "The Nation (Reuters)", "url": "https://www.nationthailand.com/news/world/40073309"}, {"portal": "The Rio Times", "url": "https://www.riotimesonline.com/?p=786167"}]'::jsonb),
  ('2026-11-17', '2026-11-17T08:55:00-03:00', 'El lunes fue malo para los activos argentinos: el riesgo país subió a 855 puntos, el Merval cayó más de 6% medido en dólares y el dólar mayorista tocó $1.551, arrastrados por la venta en Wall Street y las dudas sobre cómo se pagan los vencimientos de 2027. Afuera pesa una Reserva Federal que el mercado ya da por hecho que sube la tasa en diciembre, con el bono a 10 años de EE.UU. arriba de 5,1%. Hoy el dato a mirar es si el riesgo país logra volver debajo de 850 puntos y cómo reacciona Wall Street a las ventas minoristas de octubre en EE.UU.', '{"explicacion": "Predomina un sesgo negativo en ambos frentes: tasas de EE.UU. altas y la corrección tecnológica explican buena parte de la caída local, a lo que se suma el ruido propio por la deuda de 2027 y la inflación de octubre. El superávit fiscal de octubre y el petróleo más barato amortiguan algo, pero no alcanzan a dar vuelta el tono. No se suman las noticias: la caída del lunes ya refleja en parte el shock global.", "factorAR": -0.45, "factorGlobal": -0.4}'::jsonb, '[{"ajustes": {}, "ambito": "Argentina", "canal": "Golpea de lleno a bonos soberanos, acciones locales y obligaciones negociables, mientras el dólar que sube erosiona lo que está en pesos.", "confianza": "alta", "factorAR": -0.25, "factorGlobal": -0.05, "fuente": "La Capital", "horizonte": "días", "id": "lunes-rojo-riesgo-pais-855", "resumen": "El lunes 16 el riesgo país subió 25 puntos a 855, el MSCI Merval cayó 4,3% en pesos (81.476 puntos) y 6,1% en dólares, y los ADR perdieron hasta 7,7%. El mayorista cerró en $1.551, el MEP en $1.584,84 y el CCL en $1.684,10; el BCRA compró US$33 millones pero las reservas quedaron debajo de US$50.000 millones.", "titulo": "Riesgo país sube a 855 puntos, el Merval cae 6,1% en dólares y el dólar mayorista llega a $1.551", "url": "https://www.lacapital.com.ar/economia/mercados-cayeron-las-acciones-y-los-bonos-el-riesgo-pais-salto-855-puntos-y-el-dolar-volvio-subir-n10292518.html"}, {"ajustes": {"cer": 0.05, "pesos": -0.03}, "ambito": "Argentina", "canal": "Una inflación más alta favorece a los bonos que ajustan por CER frente a los de tasa fija y complica la baja de tasas en pesos.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": 0, "fuente": "iProUP", "horizonte": "semanas", "id": "inflacion-octubre-2-2", "resumen": "El IPC de octubre subió 2,2% (1,9% en septiembre), con 33,1% interanual y 26,3% acumulado en el año; lo empujaron tarifas de gas (Vivienda +4,2%) y estacionales (+5,5%). La núcleo fue 1,5%, la más baja en 15 meses.", "titulo": "La inflación de octubre fue 2,2%, la más alta en seis meses, pero la núcleo bajó a 1,5%", "url": "https://www.iproup.com/finanzas/73103-inflacion-de-octubre-llega-a-22-y-marca-su-nivel-mas-alto-en-6-meses"}, {"ajustes": {"soberanos": -0.03}, "ambito": "Argentina", "canal": "Las dudas sobre el financiamiento de 2027, año electoral, presionan el precio de los bonos en dólares y suben el riesgo país.", "confianza": "media", "factorAR": -0.2, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "meses", "id": "ieral-faltante-2027", "resumen": "Según IERAL, los vencimientos del Tesoro y el BCRA en 2027 suman US$28.000 millones, con US$5.600 millones netos al FMI, y con las fuentes hoy disponibles faltarían US$17.000 millones. JP Morgan anticipa que la inflación difícilmente perfore el 2% mensual antes de las elecciones.", "titulo": "IERAL estima un faltante de US$17.000 millones para pagar la deuda de 2027", "url": "https://www.infobae.com/economia/2026/11/16/las-acciones-y-los-bonos-argentinos-cotizan-en-baja-y-vuelve-a-subir-el-riesgo-pais/"}, {"ajustes": {"soberanos": 0.02}, "ambito": "Argentina", "canal": "Sostiene la capacidad de pago del Tesoro y le da un piso a los bonos soberanos.", "confianza": "alta", "factorAR": 0.15, "factorGlobal": 0, "fuente": "The Rio Times", "horizonte": "semanas", "id": "superavit-primario-octubre", "resumen": "El resultado primario de octubre fue de ARS 1,93 billones (unos US$1.250 millones) y el financiero de ARS 1,58 billones; en diez meses el primario ronda 1,4% del PIB, igual a la meta anual del FMI. Caputo advirtió que diciembre, por gastos estacionales, pondrá a prueba el cierre del año.", "titulo": "Superávit primario de $1,93 billones en octubre; el acumulado llega a la meta anual con el FMI", "url": "https://www.riotimesonline.com/argentina-budget-surplus-october-2026/"}, {"ajustes": {"cedears": -0.04}, "ambito": "Mundo", "canal": "Pega directo en los CEDEARs y contagia a los activos de riesgo emergentes, incluidas las acciones argentinas.", "confianza": "media", "factorAR": -0.1, "factorGlobal": -0.35, "fuente": "The Rio Times", "horizonte": "días", "id": "wall-street-cae-1-9", "resumen": "El S&P 500 cayó 1,92% el lunes a 7.417 puntos y el VIX saltó 18,7% a 22,91; la tasa del bono a 10 años de EE.UU. quedó en 5,138%, 24 puntos más que cinco ruedas atrás.", "titulo": "Wall Street cae 1,92% por la venta en tecnológicas y el índice del miedo sube a 22,9", "url": "https://www.riotimesonline.com/brazils-financial-morning-call-for-tuesday-november-17-2026/"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. encarecen el financiamiento para emergentes y le quitan atractivo a los bonos argentinos y a las acciones de crecimiento.", "confianza": "alta", "factorAR": -0.15, "factorGlobal": -0.25, "fuente": "Reuters (vía GV Wire)", "horizonte": "semanas", "id": "fed-suba-diciembre", "resumen": "Los operadores descuentan por completo una suba de la Fed en diciembre y asignan cerca de 7% a una de 50 puntos básicos, según CME FedWatch. La renuncia de Jensen Huang como CEO de Nvidia arrastró al índice de semiconductores, que cayó 5% el viernes 13.", "titulo": "El mercado da por hecho que la Fed sube la tasa en diciembre tras la salida de Huang de Nvidia", "url": "https://gvwire.com/2026/11/13/wall-street-reverses-early-gains-as-nvidia-fallout-rattles-tech-stocks/"}, {"ajustes": {"merval": -0.03, "ons": -0.02}, "ambito": "Mundo", "canal": "Un petróleo más barato alivia la inflación global pero recorta ingresos de Vaca Muerta y pesa sobre YPF, Vista y sus obligaciones negociables.", "confianza": "media", "factorAR": -0.05, "factorGlobal": 0.1, "fuente": "OilPrice.com", "horizonte": "semanas", "id": "brent-cae-noviembre", "resumen": "Desde el inicio de noviembre el Brent perdió alrededor de 21% y opera en la zona de US$92-94, con Arabia Saudita produciendo cerca de niveles previos a la guerra; Irán niega negociar con Washington, lo que mantiene el riesgo de rebotes.", "titulo": "El Brent cae cerca de 21% en noviembre por esperanzas de paz con Irán y exceso de oferta", "url": "https://oilprice.com/Latest-Energy-News/World-News/Brent-Jumps-3-to-94-as-Iran-Denies-Any-Talks-With-Washington.html"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Un real débil le resta competitividad a Argentina y suma presión al tipo de cambio y a las empresas que exportan a Brasil.", "confianza": "media", "factorAR": -0.1, "factorGlobal": -0.05, "fuente": "The Rio Times", "horizonte": "semanas", "id": "brasil-real-debil", "resumen": "Tras el balotaje del 25 de octubre el Ibovespa cayó 16,83% en 20 ruedas (172.060 puntos el 11/11) y el dólar subió 11% frente al real, a 5,58; la Selic quedó en 13,75% y el gobierno prepara un ajuste fiscal para 2027.", "titulo": "Brasil: el Ibovespa acumula -16,8% en 20 ruedas y el real ronda su peor nivel en un año", "url": "https://www.riotimesonline.com/brazil-markets-ibovespa-real-wednesday-november-11-2026/"}]'::jsonb, '[{"descripcion": "La Fed sube 25 pb en diciembre y deja abiertas más subas, el bono a 10 años pasa 5,3% y la corrección tecnológica se extiende; el riesgo país vuelve arriba de 950 desde 855.", "dolar": 6, "id": "tormenta-global", "nombre": "Sigue la tormenta global", "petroleo": -5, "prob": 25, "riesgoPais": 120, "senales": ["El S&P 500 perfora 7.300 puntos y el VIX sigue arriba de 25", "El bono del Tesoro a 10 años supera 5,25%"], "spx": -8, "tasas": 25}, {"descripcion": "Wall Street se estabiliza tras caer 1,92% el lunes y el riesgo país oscila entre 820 y 900 puntos, con el dólar mayorista subiendo de a poco desde $1.551 dentro de la banda.", "dolar": 3, "id": "volatilidad-con-piso", "nombre": "Volatilidad con piso", "petroleo": 0, "prob": 35, "riesgoPais": 20, "senales": ["El riesgo país se mueve en un rango de 820-900 sin romperlo", "El BCRA sigue comprando dólares de a decenas de millones por día"], "spx": -2, "tasas": 10}, {"descripcion": "El superávit de 1,4% del PIB se sostiene, el gobierno muestra fuentes nuevas para 2027 y los datos de EE.UU. moderan la suba de la Fed; el riesgo país vuelve hacia 730.", "dolar": 1.5, "id": "rebote-fiscal", "nombre": "Rebote por fiscal y alivio externo", "petroleo": -5, "prob": 20, "riesgoPais": -120, "senales": ["Anuncio de nuevo financiamiento (repo, organismos o emisión) para 2027", "El PCE núcleo de octubre (25/11) sale en 0,2% o menos"], "spx": 5, "tasas": -10}, {"descripcion": "Las dudas sobre los US$17.000 millones que faltarían para 2027 y las encuestas electorales disparan la cobertura: el riesgo país supera 1.100 y el dólar se acerca al techo de la banda de $1.971.", "dolar": 12, "id": "estres-local-2027", "nombre": "Estrés local por 2027", "petroleo": 0, "prob": 12, "riesgoPais": 250, "senales": ["El CCL supera $1.800 y la brecha con el mayorista pasa 15%", "Las reservas brutas caen debajo de US$47.000 millones"], "spx": -3, "tasas": 15}, {"descripcion": "Se cortan las negociaciones y vuelven los ataques en Ormuz: el Brent sube de US$92 a más de US$110, reaviva la inflación en EE.UU. y empuja más subas de la Fed.", "dolar": 4, "id": "shock-petrolero-iran", "nombre": "Rebrote del conflicto con Irán", "petroleo": 20, "prob": 8, "riesgoPais": 60, "senales": ["El Brent vuelve a superar US$105", "Nuevos ataques o minas contra buques en el estrecho de Ormuz"], "spx": -5, "tasas": 20}]'::jsonb, '[{"portal": "La Capital", "url": "https://www.lacapital.com.ar/economia/mercados-cayeron-las-acciones-y-los-bonos-el-riesgo-pais-salto-855-puntos-y-el-dolar-volvio-subir-n10292518.html"}, {"portal": "iProUP", "url": "https://www.iproup.com/finanzas/73103-inflacion-de-octubre-llega-a-22-y-marca-su-nivel-mas-alto-en-6-meses"}, {"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/16/las-acciones-y-los-bonos-argentinos-cotizan-en-baja-y-vuelve-a-subir-el-riesgo-pais/"}, {"portal": "The Rio Times", "url": "https://www.riotimesonline.com/argentina-budget-surplus-october-2026/"}, {"portal": "The Rio Times", "url": "https://www.riotimesonline.com/brazils-financial-morning-call-for-tuesday-november-17-2026/"}, {"portal": "Reuters (vía GV Wire)", "url": "https://gvwire.com/2026/11/13/wall-street-reverses-early-gains-as-nvidia-fallout-rattles-tech-stocks/"}, {"portal": "OilPrice.com", "url": "https://oilprice.com/Latest-Energy-News/World-News/Brent-Jumps-3-to-94-as-Iran-Denies-Any-Talks-With-Washington.html"}, {"portal": "The Rio Times", "url": "https://www.riotimesonline.com/brazil-markets-ibovespa-real-wednesday-november-11-2026/"}]'::jsonb),
  ('2026-11-18', '2026-11-18T08:50:00-03:00', 'Los activos argentinos siguen castigados: el riesgo país quedó en torno a 855 puntos, los dólares financieros subieron 1% (MEP $1.600, CCL $1.696) y la región sufre por las tasas altas en EE.UU. y la caída del real brasileño. Afuera, Nvidia mostró ventas récord y le devolvió algo de aire a Wall Street, pero la Reserva Federal sigue encaminada a subir la tasa en diciembre. El dato a mirar hoy es si el oficialismo consigue en el Senado el dictamen para suspender las PASO, que el mercado lee como una buena noticia para los bonos.', '{"explicacion": "Pesa más lo local: riesgo país alto, brecha que se amplía, inflación de 2,2% e incertidumbre electoral, apenas compensado por la chance de que se suspendan las PASO. En lo global, el buen balance de Nvidia y la Fed más dura se compensan casi por completo; no se suman por separado la caída del real y la salida de fondos de la región porque responden a las mismas tasas altas de EE.UU.", "factorAR": -0.25, "factorGlobal": -0.05}'::jsonb, '[{"ajustes": {}, "ambito": "Argentina", "canal": "Bonos soberanos, ONs y acciones locales en dólares pierden valor cuando sube el riesgo país, y se encarece el financiamiento de empresas y del Tesoro.", "confianza": "alta", "factorAR": -0.2, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "días", "id": "riesgo-pais-855", "resumen": "El riesgo país subió 21 unidades (+3%) a 855 pb el lunes 16 y el Merval perdió 4,9%; el martes rondó 846-859 pb. Desde el mínimo de 403 pb de julio, el indicador más que se duplicó.", "titulo": "El riesgo país saltó a 855 puntos y el Merval cayó 4,9% en un lunes negro", "url": "https://www.infobae.com/economia/2026/11/17/se-suman-fantasmas-a-la-incertidumbre-electoral-los-factores-que-golpearon-a-la-argentina-y-empujaron-al-riesgo-pais/"}, {"ajustes": {"soberanos": 0.03}, "ambito": "Argentina", "canal": "Si se aprueba, baja la prima de riesgo político y suben los bonos en dólares y las acciones; si fracasa, se refuerza el pesimismo actual.", "confianza": "media", "factorAR": 0.3, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "semanas", "id": "suspension-paso", "resumen": "El Gobierno no consiguió el dictamen el martes y vuelve a intentarlo hoy; si lo logra, el proyecto iría al recinto del Senado el jueves 26. Bancos y fondos creen que acortaría el período de turbulencia preelectoral de 2027.", "titulo": "El oficialismo busca dictamen para suspender las PASO; el mercado lo ve como \"evento positivo\"", "url": "https://www.infobae.com/economia/2026/11/18/el-factor-politico-que-podria-darle-aire-al-riesgo-pais-y-que-el-mercado-ve-como-un-evento-positivo/"}, {"ajustes": {"pesos": -0.03}, "ambito": "Argentina", "canal": "Una brecha más ancha y pagos en dólares del Tesoro presionan sobre el peso: castigan las colocaciones en pesos medidas en dólares.", "confianza": "media", "factorAR": -0.15, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "semanas", "id": "dolares-financieros-brecha", "resumen": "El MEP cerró en $1.600 y el CCL en $1.696 (+1%), con el mayorista en $1.552; el BCRA compró USD 74 millones y las reservas quedaron en USD 49.741 millones. El canje de la Lelink adhirió 60,2% y el Tesoro deberá pagar USD 1.889 millones.", "titulo": "Suben MEP y CCL 1%, se amplía la brecha y el Tesoro renovó solo 60% de la letra dólar linked", "url": "https://www.infobae.com/economia/2026/11/18/suben-los-dolares-financieros-y-se-amplia-la-brecha-mientras-un-indicador-global-enciende-las-alarmas-en-el-mercado/"}, {"ajustes": {"cer": 0.03, "pesos": -0.02}, "ambito": "Argentina", "canal": "Más inflación favorece a los bonos CER frente a las tasas fijas en pesos y amplía el margen para que suba el dólar oficial.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": 0, "fuente": "Perfil", "horizonte": "semanas", "id": "inflacion-octubre-22", "resumen": "El IPC subió 2,2% en octubre (el REM esperaba 1,8%), el más alto desde abril. Con ese dato, el techo de la banda pasa de $1.989,12 a fin de noviembre a $2.032,88 el 31 de diciembre.", "titulo": "La inflación de octubre fue 2,2% y el techo de la banda cambiaria superará los $2.000 en diciembre", "url": "https://perfil.com/economia/dolar-oficial-tras-la-inflacion-de-octubre-el-bcra-fijo-un-nuevo-techo-para-la-banda-cambiaria-aJzZx7s5GmOb"}, {"ajustes": {"pesos": -0.02}, "ambito": "Argentina", "canal": "El atraso cambiario sostenido aumenta el riesgo de una corrección del peso, que golpearía a quien tenga activos en pesos.", "confianza": "media", "factorAR": -0.1, "factorGlobal": 0, "fuente": "iProfesional", "horizonte": "meses", "id": "atraso-cambiario-dolarizacion", "resumen": "En 2026 el dólar minorista subió cerca de 5,7% contra una inflación de 23,6% a septiembre; el tipo de cambio real ronda 83 puntos. Los particulares compraron unos USD 2.500 millones en octubre y la demanda anual se proyecta en USD 30.000 millones.", "titulo": "Dólar atrasado frente a la inflación y ahorristas que compran USD 2.500 millones por mes", "url": "https://www.iprofesional.com/finanzas/468192-dolar-margen-subir-fuerte-alerta-compran-divisas-noviembre-2026"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Alivia el temor sobre la inteligencia artificial y sostiene a los CEDEARs tecnológicos y al apetito por riesgo en general.", "confianza": "media", "factorAR": 0.05, "factorGlobal": 0.3, "fuente": "Yahoo Finance (The Motley Fool)", "horizonte": "días", "id": "nvidia-resultados-q3", "resumen": "Las ventas crecieron 103% interanual y la guía para el próximo trimestre (unos USD 130.000 millones) superó lo esperado. Antes del dato, el S&P 500 había caído 1,03% a 7.341 puntos y el VIX llegó a 25,45.", "titulo": "Nvidia vendió USD 115.800 millones y proyecta 130.000; sus acciones subieron fuera de hora", "url": "https://finance.yahoo.com/markets/stocks/articles/stock-market-today-nov-17-222310679.html"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. sacan fondos de emergentes, presionan bonos argentinos y bajan las valuaciones de acciones globales.", "confianza": "alta", "factorAR": -0.15, "factorGlobal": -0.3, "fuente": "Investing.com", "horizonte": "semanas", "id": "fed-subas-bofa", "resumen": "Tras un IPC de octubre de 0,4% mensual, BofA espera subas de 25 pb en diciembre, enero y marzo hasta 4,5%-4,75%. La tasa a 10 años de EE.UU. ronda 5,1%.", "titulo": "BofA ya ve tres subas de la Fed seguidas: diciembre, enero y marzo", "url": "https://www.investing.com/news/economy-news/bofa-now-sees-fed-hiking-in-january-lifts-terminal-rate-forecast-5024869"}, {"ajustes": {"merval": -0.02}, "ambito": "Mundo", "canal": "Un real débil le quita competitividad a la Argentina y arrastra el ánimo inversor sobre toda la región.", "confianza": "media", "factorAR": -0.1, "factorGlobal": -0.05, "fuente": "The Rio Times", "horizonte": "semanas", "id": "brasil-real-debil", "resumen": "El Ibovespa cae 16,8% en 20 ruedas y está 17,7% debajo de su pico de octubre; la Selic sigue en 13,75%. El lunes el real se devaluó más de 2% hasta 5,79 por dólar.", "titulo": "El real brasileño se hunde: 5,79 por dólar y 16% de caída desde el balotaje", "url": "https://riotimesonline.com/brazil-markets-ibovespa-real-wednesday-november-11-2026"}]'::jsonb, '[{"descripcion": "El riesgo país se queda entre 800 y 900 pb y la Fed sube 25 pb en diciembre como espera el mercado. El dólar oficial acompaña la banda sin saltos desde los $1.552 actuales.", "dolar": 2, "id": "lateral-con-ruido", "nombre": "Lateral con ruido", "petroleo": 0, "prob": 35, "riesgoPais": 0, "senales": ["Riesgo país estable entre 800 y 900 pb", "Fed sube 25 pb el 9 de diciembre sin anticipar más"], "spx": 1, "tasas": 25}, {"descripcion": "El Senado suspende las PASO el 26 de noviembre y el rebote de Nvidia contagia a Wall Street. El riesgo país vuelve hacia 730 pb.", "dolar": 1, "id": "paso-y-alivio-ia", "nombre": "Sin PASO y alivio de la IA", "petroleo": -5, "prob": 20, "riesgoPais": -120, "senales": ["Aprobación de la reforma política en el Senado", "Riesgo país perfora 800 pb y el VIX baja de 20"], "spx": 5, "tasas": 10}, {"descripcion": "Los datos de PCE (25/11) y empleo (4/12) salen calientes y el mercado pasa a esperar 50 pb; la tasa a 10 años supera 5,3% desde 5,1%. Salen fondos de emergentes.", "dolar": 3, "id": "fed-mas-dura", "nombre": "Fed más dura", "petroleo": 0, "prob": 20, "riesgoPais": 80, "senales": ["PCE núcleo de octubre de 0,4% o más", "Futuros asignan más de 50% a una suba de 50 pb"], "spx": -6, "tasas": 60}, {"descripcion": "La brecha sigue abriéndose, cae la oferta de exportadores y el dólar mayorista corre hacia el techo de la banda ($1.989 en noviembre, $2.033 en diciembre). El riesgo país supera 1.000 pb.", "dolar": 10, "id": "estres-cambiario-local", "nombre": "Estrés cambiario local", "petroleo": 0, "prob": 15, "riesgoPais": 180, "senales": ["MEP y CCL por encima de $1.700", "El BCRA deja de comprar y caen las reservas debajo de USD 48.000 millones"], "spx": -2, "tasas": 25}, {"descripcion": "Los ataques en el estrecho de Ormuz cortan flujos reales y el Brent salta desde los USD 92-93 a más de 105. Sube la inflación global y la aversión al riesgo.", "dolar": 3, "id": "escalada-iran", "nombre": "Escalada con Irán", "petroleo": 15, "prob": 10, "riesgoPais": 60, "senales": ["Brent por encima de USD 100", "Ataques confirmados a infraestructura de exportación del Golfo"], "spx": -4, "tasas": 15}]'::jsonb, '[{"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/17/se-suman-fantasmas-a-la-incertidumbre-electoral-los-factores-que-golpearon-a-la-argentina-y-empujaron-al-riesgo-pais/"}, {"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/18/el-factor-politico-que-podria-darle-aire-al-riesgo-pais-y-que-el-mercado-ve-como-un-evento-positivo/"}, {"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/18/suben-los-dolares-financieros-y-se-amplia-la-brecha-mientras-un-indicador-global-enciende-las-alarmas-en-el-mercado/"}, {"portal": "Perfil", "url": "https://perfil.com/economia/dolar-oficial-tras-la-inflacion-de-octubre-el-bcra-fijo-un-nuevo-techo-para-la-banda-cambiaria-aJzZx7s5GmOb"}, {"portal": "iProfesional", "url": "https://www.iprofesional.com/finanzas/468192-dolar-margen-subir-fuerte-alerta-compran-divisas-noviembre-2026"}, {"portal": "Yahoo Finance (The Motley Fool)", "url": "https://finance.yahoo.com/markets/stocks/articles/stock-market-today-nov-17-222310679.html"}, {"portal": "Investing.com", "url": "https://www.investing.com/news/economy-news/bofa-now-sees-fed-hiking-in-january-lifts-terminal-rate-forecast-5024869"}, {"portal": "The Rio Times", "url": "https://riotimesonline.com/brazil-markets-ibovespa-real-wednesday-november-11-2026"}]'::jsonb),
  ('2026-11-19', '2026-11-19T09:05:00-03:00', 'El mercado argentino sigue a la defensiva: el riesgo país ronda los 850 puntos, el dólar oficial marca récords nominales y la brecha con el contado con liquidación ya toca el 10%. Afuera pesa una Reserva Federal que se prepara para subir la tasa en diciembre, con el bono a 10 años de EE.UU. arriba del 5%, mientras la inteligencia artificial vuelve a decidir el humor de Wall Street. El dato a mirar hoy es el debut de Anthropic en el Nasdaq y si el riesgo país logra sostenerse debajo de los 850 puntos con compras del BCRA que no se apaguen.', '{"explicacion": "Dominan las noticias negativas locales (riesgo político 2027, presión sobre la brecha, compras del BCRA más flojas, inflación de 2,2%) y una Fed más dura afuera; el rebote esperado por el debut de Anthropic y el petróleo más barato compensan solo en parte. No se suman: el dato de la Fed y la salida de emergentes son en buena medida el mismo shock de tasas.", "factorAR": -0.3, "factorGlobal": -0.15}'::jsonb, '[{"ajustes": {"merval": -0.03}, "ambito": "Argentina", "canal": "Con el riesgo país arriba de 800 puntos se traba la emisión de deuda prevista y bajan los precios de soberanos y acciones bancarias.", "confianza": "media", "factorAR": -0.15, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "riesgo-pais-850-paso", "resumen": "El riesgo país cerró el martes 17 en 854 puntos y el MSCI Merval cayó 0,4% a 81.794; el lunes el Merval en dólares había perdido casi 5%, con bancos hasta -7,7%. En octubre hubo superávit primario de $1,9 billones, aunque los ingresos reales cayeron 1,5% interanual.", "titulo": "El riesgo país sigue en torno a 850 puntos mientras el Congreso debate suspender las PASO 2027", "url": "https://www.ambito.com/finanzas/los-bonos-dolares-vuelven-abrir-negativo-wall-street-y-el-riesgo-pais-ya-supera-los-850-puntos-basicos-n6346069"}, {"ajustes": {"pesos": -0.04}, "ambito": "Argentina", "canal": "Más demanda de cobertura y menos compras oficiales presionan la brecha y restan atractivo a las colocaciones en pesos.", "confianza": "media", "factorAR": -0.2, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "dolar-record-brecha-10", "resumen": "El miércoles 18 el BCRA compró apenas US$11 millones (contra US$74 millones el martes) y las reservas bajaron US$190 millones por la caída del oro. El mayorista hiló tres subas y marcó máximos nominales, mientras el Merval acumula una pérdida del 34% en dólares desde julio.", "titulo": "Dólar mayorista en récord, blue a $1.630 y CCL arriba de $1.700: la brecha toca el 10%", "url": "https://www.ambito.com/finanzas/dolar-hoy-y-dolar-blue-hoy-minuto-minuto-cuanto-opera-este-miercoles-18-noviembre-n6346477"}, {"ajustes": {"soberanos": -0.02}, "ambito": "Argentina", "canal": "Confirma que la prima de riesgo es mayormente política, lo que hace a los bonos largos sensibles a encuestas y señales del Congreso.", "confianza": "media", "factorAR": -0.1, "factorGlobal": 0, "fuente": "iProfesional", "horizonte": "meses", "id": "caputo-riesgo-politico-2027", "resumen": "El ministro dijo que el riesgo país pasó de unos 400 a cerca de 950 puntos por el shock externo y por el miedo a un cambio de gobierno, y que las tasas implícitas posteriores a 2027 rondan el 30%. Aseguró que el programa financiero de 2027 está cerrado y proyectó inversiones RIGI por US$15.000 millones.", "titulo": "Caputo admite menor crecimiento y atribuye la suba del riesgo país al temor electoral de 2027", "url": "https://www.iprofesional.com/economia/469216-caputo-explico-por-que-no-llegaron-los-mejores-18-meses-de-la-economia"}, {"ajustes": {"cer": 0.05, "pesos": -0.02}, "ambito": "Argentina", "canal": "Favorece a los bonos CER frente a la tasa fija y erosiona el atraso cambiario, sumando presión al dólar.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": 0, "fuente": "iProUP", "horizonte": "semanas", "id": "inflacion-octubre-22", "resumen": "El IPC subió 2,2% mensual (REM esperaba cerca de 2%), acumula 26,3% en el año y 33,1% interanual. Los regulados subieron 2,9% y los estacionales 5,5%, mientras la núcleo marcó 1,5%, mínimo en 15 meses.", "titulo": "La inflación de octubre fue 2,2%, la más alta en seis meses, aunque la núcleo bajó a 1,5%", "url": "https://www.iproup.com/finanzas/73103-inflacion-de-octubre-llega-a-22-y-marca-su-nivel-mas-alto-en-6-meses"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas de EE.UU. más altas encarecen el financiamiento de emergentes, empujan el riesgo país y pesan sobre los CEDEARs.", "confianza": "alta", "factorAR": -0.15, "factorGlobal": -0.35, "fuente": "Investing.com", "horizonte": "semanas", "id": "fed-waller-suba-diciembre", "resumen": "El mercado da casi 95% de probabilidad a una suba de 25 pb en diciembre y 5% a una de 50 pb; la tasa a 10 años quedó en 5,09%. El S&P 500 cerró en 7.321 (-0,3%) y el Dow cayó 1,1%.", "titulo": "Waller pide subir 50 pb y las actas de la Fed respaldan más subas: el bono a 10 años supera el 5%", "url": "https://www.investing.com/news/stock-market-news/us-stock-futures-jump-as-nvidia-earnings-revive-ai-optimism-5034391"}, {"ajustes": {"cedears": 0.03}, "ambito": "Mundo", "canal": "Si el debut sale bien puede calmar la venta de tecnológicas y sostener a los CEDEARs, con poco efecto directo sobre activos locales.", "confianza": "media", "factorAR": 0.03, "factorGlobal": 0.2, "fuente": "Investing.com", "horizonte": "días", "id": "anthropic-ipo-nvidia", "resumen": "Anthropic recaudó US$107.300 millones a US$83 por acción, con una valuación de US$1,5 billones, y se esperaba que abriera hasta 26% arriba. Los futuros del S&P 500 subían 1,1% y los del Nasdaq 100 1,9%, mientras Nvidia cayó 2,9% pese a ingresos de casi US$116.000 millones.", "titulo": "Anthropic debuta en el Nasdaq tras una salida récord y los futuros suben pese a la caída de Nvidia", "url": "https://www.investing.com/news/economy-news/anthropics-recordsetting-ipo-fed-minutes--whats-moving-markets-5038148"}, {"ajustes": {"ons": -0.02}, "ambito": "Mundo", "canal": "Menos apetito por emergentes reduce la demanda de soberanos y ONs argentinas y presiona el Merval.", "confianza": "media", "factorAR": -0.1, "factorGlobal": -0.1, "fuente": "Ámbito", "horizonte": "semanas", "id": "emergentes-salida-60000m", "resumen": "Según el IIF, en octubre salieron US$33.800 millones de emergentes y América Latina perdió US$1.700 millones. El IIF advierte que los flujos dependen de que la tasa a 10 años de EE.UU. quede debajo de 5,3% y del petróleo.", "titulo": "Se fueron más de US$60.000 millones de los emergentes en dos meses por dudas sobre la IA", "url": "https://www.ambito.com/economia/mercados-emergentes-se-fugaron-mas-us60000-millones-dos-meses-y-crece-el-temor-la-crisis-la-ia-n6346444"}, {"ajustes": {"merval": -0.02, "ons": -0.02}, "ambito": "Mundo", "canal": "Petróleo más barato alivia la inflación global y las tasas, pero reduce ingresos de energéticas argentinas; un ataque a Irán lo revertiría.", "confianza": "baja", "factorAR": 0, "factorGlobal": 0.1, "fuente": "The Nation (Reuters)", "horizonte": "semanas", "id": "brent-superavit-iran", "resumen": "El Brent cayó 3,55% a US$92,44 el 16 de noviembre tras la proyección de la AIE de un excedente de 1,7 millones de barriles diarios en el cuarto trimestre; Goldman ve US$88 de promedio en 2027. Siguen los ataques a buques en Ormuz.", "titulo": "El Brent ronda US$92 por el superávit previsto por la AIE, pero Trump evalúa nuevos ataques a Irán", "url": "https://www.nationthailand.com/news/world/40073582"}]'::jsonb, '[{"descripcion": "La Fed sube 25 pb en diciembre como espera el mercado y el riesgo país oscila entre 800 y 900 puntos. El dólar mayorista sigue subiendo de a poco desde $1.552, lejos del techo de la banda.", "dolar": 3, "id": "volatilidad-contenida", "nombre": "Volatilidad contenida", "petroleo": 0, "prob": 35, "riesgoPais": 0, "senales": ["Riesgo país entre 800 y 900 puntos durante dos semanas", "BCRA comprando más de US$30 millones diarios en promedio"], "spx": 0, "tasas": 25}, {"descripcion": "Un buen debut de Anthropic reactiva a las tecnológicas, el Brent baja de US$90 por el superávit y vuelven flujos a emergentes. El riesgo país retrocede hacia 730 puntos con avance de la agenda legislativa.", "dolar": 2, "id": "rebote-ia-calma", "nombre": "Rebote por IA y calma", "petroleo": -5, "prob": 20, "riesgoPais": -120, "senales": ["S&P 500 recupera los 7.500 puntos", "Riesgo país perfora los 800 puntos"], "spx": 6, "tasas": 0}, {"descripcion": "Datos de inflación altos llevan a la Fed a subir 50 pb como pide Waller y el bono a 10 años supera el 5,3% del máximo de octubre. Siguen las salidas de emergentes y el riesgo país vuelve a la zona de 950.", "dolar": 4, "id": "fed-agresiva", "nombre": "Fed agresiva", "petroleo": 0, "prob": 20, "riesgoPais": 100, "senales": ["Tasa a 10 años de EE.UU. arriba de 5,3%", "FedWatch con más de 40% de probabilidad de suba de 50 pb"], "spx": -7, "tasas": 60}, {"descripcion": "El ruido político por 2027 y la caída de las compras del BCRA disparan la demanda de cobertura; el CCL ya está arriba de $1.700 con brecha de 10%. El riesgo país supera los 1.100 puntos y el Tesoro no logra financiarse para enero.", "dolar": 12, "id": "estres-local-2027", "nombre": "Estrés local 2027", "petroleo": 0, "prob": 15, "riesgoPais": 250, "senales": ["Brecha con el CCL por encima de 15%", "Reservas brutas debajo de US$48.000 millones"], "spx": -2, "tasas": 25}, {"descripcion": "Trump decide nuevos ataques sobre Irán y el Brent pasa de US$92 a más de US$110 con cortes en Ormuz. Sube la inflación global, se aleja cualquier alivio de tasas y castiga a emergentes.", "dolar": 5, "id": "shock-iran", "nombre": "Shock por Irán", "petroleo": 20, "prob": 10, "riesgoPais": 120, "senales": ["Brent arriba de US$105", "Anuncio oficial de ataques de EE.UU. a Irán"], "spx": -5, "tasas": 20}]'::jsonb, '[{"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/los-bonos-dolares-vuelven-abrir-negativo-wall-street-y-el-riesgo-pais-ya-supera-los-850-puntos-basicos-n6346069"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/dolar-hoy-y-dolar-blue-hoy-minuto-minuto-cuanto-opera-este-miercoles-18-noviembre-n6346477"}, {"portal": "iProfesional", "url": "https://www.iprofesional.com/economia/469216-caputo-explico-por-que-no-llegaron-los-mejores-18-meses-de-la-economia"}, {"portal": "iProUP", "url": "https://www.iproup.com/finanzas/73103-inflacion-de-octubre-llega-a-22-y-marca-su-nivel-mas-alto-en-6-meses"}, {"portal": "Investing.com", "url": "https://www.investing.com/news/stock-market-news/us-stock-futures-jump-as-nvidia-earnings-revive-ai-optimism-5034391"}, {"portal": "Investing.com", "url": "https://www.investing.com/news/economy-news/anthropics-recordsetting-ipo-fed-minutes--whats-moving-markets-5038148"}, {"portal": "Ámbito", "url": "https://www.ambito.com/economia/mercados-emergentes-se-fugaron-mas-us60000-millones-dos-meses-y-crece-el-temor-la-crisis-la-ia-n6346444"}, {"portal": "The Nation (Reuters)", "url": "https://www.nationthailand.com/news/world/40073582"}]'::jsonb),
  ('2026-11-20', '2026-11-20T08:55:00-03:00', 'Ayer fue un mal día para todo lo argentino: el riesgo país saltó casi 10% hasta 931 puntos, los bonos en dólares cayeron hasta 3,3% y los ADRs hasta 10,4%, mientras el dólar mayorista marcó récord nominal en $1.565 y la brecha con el CCL pasó el 11%. Afuera tampoco ayuda: Wall Street encadenó seis bajas, la tasa a 10 años de EE.UU. está arriba del 5% y el mercado da casi por segura una suba de tasas de la Fed en diciembre, mientras el real brasileño se acerca a 6 por dólar. El dato a mirar hoy es si el riesgo país se queda arriba de 900 puntos y si el BCRA vuelve a comprar dólares después de haber sumado apenas u$s3 millones ayer.', '{"explicacion": "El golpe local (riesgo país, dólar, poca compra de reservas, dudas por la refinanciación y el contagio de Brasil) comparte en buena parte una misma causa con el ajuste global por la Fed más dura, así que no se suma todo: queda un tono claramente negativo para activos argentinos (-0,6) y moderadamente negativo para bolsas y tasas del mundo (-0,45). El superávit comercial récord compensa sólo un poco.", "factorAR": -0.6, "factorGlobal": -0.45}'::jsonb, '[{"ajustes": {"soberanos": -0.03}, "ambito": "Argentina", "canal": "Pega directo en bonos soberanos, ONs y acciones locales vía mayor tasa exigida a la deuda argentina.", "confianza": "alta", "factorAR": -0.4, "factorGlobal": -0.05, "fuente": "Ámbito", "horizonte": "días", "id": "riesgo-pais-931", "resumen": "El jueves 19 el riesgo país de JP Morgan subió 9,8% a 931 pb, la mayor suba diaria desde octubre de 2025; los Globales 2035 y 2041 perdieron 3,3% y el Merval cedió 1% (2,5% en dólares) con Supervielle -10,4% y Galicia -6,2%.", "titulo": "El riesgo país saltó 9,8% a 931 puntos y los ADRs cayeron hasta 10,4%", "url": "https://www.ambito.com/los-bonos-dolares-rebotan-medio-la-euforia-anthropic-n6347109"}, {"ajustes": {"pesos": -0.05}, "ambito": "Argentina", "canal": "Una brecha creciente y menos compras de reservas restan valor en dólares a las posiciones en pesos y presionan el riesgo país.", "confianza": "alta", "factorAR": -0.3, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "dolar-record-brecha-11", "resumen": "El mayorista cerró en $1.565, el MEP en $1.643,73 y el CCL en $1.743,48, con brecha de más de 11%, la mayor desde octubre de 2025; el BCRA compró u$s3 millones (lleva u$s16.312 millones en 2026) y las reservas cayeron u$s108 millones.", "titulo": "Dólar mayorista récord en $1.565, CCL a $1.743 y el BCRA compró solo u$s3 millones", "url": "https://www.ambito.com/finanzas/dolar-presion-la-brecha-cambiaria-alcanzo-su-nivel-mas-alto-un-ano-y-el-ccl-gana-el-centro-la-escena-n6346972"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Una licitación floja el 26 de noviembre obligaría a emitir pesos o subir tasas, lo que presiona dólar y bonos.", "confianza": "media", "factorAR": -0.15, "factorGlobal": 0, "fuente": "Forbes Argentina", "horizonte": "semanas", "id": "vencimientos-pesos-prima-electoral", "resumen": "Entre noviembre y diciembre vencen unos $74 billones de deuda en pesos y en 2027 otros $167 billones; los Globales cayeron 17% desde los máximos de julio, cuando el riesgo país tocó 402 pb, y analistas lo asocian a la prima electoral.", "titulo": "Vencen $74 billones en pesos hasta diciembre y el mercado ya cobra prima electoral 2027", "url": "https://www.forbesargentina.com/money/el-riesgo-pais-vuelve-superar-850-puntos-n102810"}, {"ajustes": {"cer": 0.05, "pesos": -0.02}, "ambito": "Argentina", "canal": "Mejora el ajuste de los bonos CER en las próximas semanas y castiga a los bonos a tasa fija.", "confianza": "media", "factorAR": -0.1, "factorGlobal": 0, "fuente": "iProUP", "horizonte": "semanas", "id": "inflacion-octubre-22", "resumen": "El IPC subió 2,2% en octubre (REM esperaba cerca de 2%), con 33,1% interanual y 26,3% acumulado; lo empujaron tarifas de gas (Vivienda 4,2%) y estacionales (5,5%), mientras la núcleo marcó 1,5%, mínimo en 15 meses.", "titulo": "La inflación de octubre fue 2,2%, la más alta en seis meses, pero la núcleo bajó a 1,5%", "url": "https://www.iproup.com/finanzas/73103-inflacion-de-octubre-llega-a-22-y-marca-su-nivel-mas-alto-en-6-meses.amp"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Más dólares comerciales ayudan a que el BCRA compre reservas, lo que sostiene bonos y el peso.", "confianza": "media", "factorAR": 0.15, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "meses", "id": "superavit-comercial-octubre", "resumen": "El superávit comercial de octubre llegó a u$s3.394 millones (u$s813 millones un año atrás), con exportaciones arriba de u$s10.000 millones (+26,4%) e importaciones -6,7%; acumula u$s24.568 millones en diez meses.", "titulo": "Superávit comercial de u$s3.394 millones en octubre con exportaciones récord", "url": "https://www.ambito.com/los-bonos-dolares-rebotan-medio-la-euforia-anthropic-n6347109"}, {"ajustes": {"merval": -0.02}, "ambito": "Mundo", "canal": "Un real débil abarata a Brasil frente a Argentina y suma presión al dólar local y a los emergentes.", "confianza": "media", "factorAR": -0.2, "factorGlobal": -0.05, "fuente": "Ámbito", "horizonte": "semanas", "id": "brasil-real-intervencion", "resumen": "El Banco Central de Brasil hizo su primera venta al contado desde diciembre de 2024, pero el real cerró en 5,9323 (-1,1%), mínimo desde abril de 2025, y acumula 15% de caída desde la reelección de Lula por dudas fiscales (déficit nominal arriba de 9% del PBI).", "titulo": "Brasil vendió u$s1.000 millones para frenar al real, que tocó 5,93 por dólar", "url": "https://www.ambito.com/finanzas/brasil-el-banco-central-vendio-us1000-millones-frenar-desplome-del-real-que-ya-perdio-15-la-reeleccion-lula-n6347373"}, {"ajustes": {"cedears": -0.02}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. encarecen el financiamiento emergente y bajan el valor de acciones y bonos largos.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.3, "fuente": "Reuters", "horizonte": "semanas", "id": "fed-minutas-suba-diciembre", "resumen": "Las minutas de octubre mostraron que la Fed ve necesarias nuevas subas y algunos miembros plantearon 50 pb si la inflación decepciona; Waller pidió más agresividad y CME FedWatch da casi 100% a una suba de 25 pb en diciembre.", "titulo": "Las minutas de la Fed anticipan más subas y el mercado da por hecha una de 25 pb en diciembre", "url": "https://www.thestar.com.my/business/business-news/2026/11/19/wall-street-ends-mixed-after-nvidia-earnings-fed-minutes"}, {"ajustes": {"cedears": -0.03}, "ambito": "Mundo", "canal": "Pega en los CEDEARs y, por aversión al riesgo, también en bonos y acciones argentinas.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.35, "fuente": "The Weekend Spread", "horizonte": "días", "id": "wall-street-seis-bajas", "resumen": "El jueves el S&P 500 (vía SPY) cayó 1,96% y 5,1% en la semana, perforando su promedio de 200 días; Nvidia bajó 3,3%, Anthropic diluyó su suba inicial de 34% a 17%, el VIX llegó a 28,29 y el Brent cerró en US$92,27.", "titulo": "Wall Street sumó seis bajas: S&P 500 -1,96%, VIX en 28 y el 10 años en 5,05%", "url": "https://theweekendspread.substack.com/p/the-close-thursday-november-19-2026"}]'::jsonb, '[{"descripcion": "El riesgo país oscila entre 850 y 950 pb, el dólar sigue subiendo de a poco lejos del techo de la banda ($1.974) y la Fed sube 25 pb en diciembre como ya está descontado.", "dolar": 3, "id": "tension-contenida", "nombre": "Tensión contenida", "petroleo": 0, "prob": 35, "riesgoPais": 20, "senales": ["Riesgo país sin superar el máximo de 939 pb del 6 de noviembre", "Licitación del 26/11 con rollover cercano al 100%"], "spx": -2, "tasas": 15}, {"descripcion": "Con el superávit comercial de u$s3.394 millones el BCRA vuelve a comprar fuerte, la licitación sale bien y el riesgo país vuelve a la zona de 780 pb; afuera, el S&P recupera su promedio de 200 días.", "dolar": 1, "id": "rebote-reservas", "nombre": "Rebote por reservas y licitación", "petroleo": -3, "prob": 20, "riesgoPais": -150, "senales": ["Compras diarias del BCRA de nuevo arriba de u$s60 millones", "Brecha CCL-mayorista bajando de 11% a menos de 8%"], "spx": 3, "tasas": 0}, {"descripcion": "Una licitación floja frente a vencimientos de $74 billones hasta diciembre obliga a liberar pesos, la brecha supera 15% y el riesgo país pasa los 1.100 pb con el oficial camino a la banda superior.", "dolar": 12, "id": "estres-cambiario-local", "nombre": "Estrés cambiario local", "petroleo": 0, "prob": 15, "riesgoPais": 250, "senales": ["Riesgo país cerrando arriba de 1.000 pb", "BCRA sin compras o vendiendo varias ruedas seguidas"], "spx": -3, "tasas": 20}, {"descripcion": "Con el 10 años ya en 5,05%, la Fed sube 50 pb o anticipa varias subas en 2027, el S&P profundiza la corrección de 5% semanal y los emergentes sufren salida de fondos.", "dolar": 4, "id": "fed-agresiva", "nombre": "Fed agresiva", "petroleo": -5, "prob": 15, "riesgoPais": 80, "senales": ["FedWatch asignando más de 30% a una suba de 50 pb en diciembre", "Tasa a 10 años de EE.UU. arriba de 5,25%"], "spx": -7, "tasas": 50}, {"descripcion": "El real pasa de 6 por dólar pese a la intervención de u$s1.000 millones y Lula demora el nombre del ministro de Hacienda, lo que contagia a Argentina vía comercio y flujos emergentes.", "dolar": 6, "id": "contagio-brasil", "nombre": "Contagio Brasil", "petroleo": -2, "prob": 10, "riesgoPais": 120, "senales": ["Real arriba de 6,10 por dólar", "Nuevas subastas de dólares del Banco Central de Brasil"], "spx": -2, "tasas": 10}, {"descripcion": "Un nuevo incidente en el Estrecho de Ormuz devuelve al Brent desde US$92 a más de US$105, reaviva la inflación global y endurece aún más a la Fed.", "dolar": 3, "id": "shock-petrolero", "nombre": "Shock petrolero en Ormuz", "petroleo": 15, "prob": 5, "riesgoPais": 60, "senales": ["Brent cerrando arriba de US$100", "Ataques a buques o infraestructura en el Golfo"], "spx": -4, "tasas": 20}]'::jsonb, '[{"portal": "Ámbito", "url": "https://www.ambito.com/los-bonos-dolares-rebotan-medio-la-euforia-anthropic-n6347109"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/dolar-presion-la-brecha-cambiaria-alcanzo-su-nivel-mas-alto-un-ano-y-el-ccl-gana-el-centro-la-escena-n6346972"}, {"portal": "Forbes Argentina", "url": "https://www.forbesargentina.com/money/el-riesgo-pais-vuelve-superar-850-puntos-n102810"}, {"portal": "iProUP", "url": "https://www.iproup.com/finanzas/73103-inflacion-de-octubre-llega-a-22-y-marca-su-nivel-mas-alto-en-6-meses.amp"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/brasil-el-banco-central-vendio-us1000-millones-frenar-desplome-del-real-que-ya-perdio-15-la-reeleccion-lula-n6347373"}, {"portal": "Reuters", "url": "https://www.thestar.com.my/business/business-news/2026/11/19/wall-street-ends-mixed-after-nvidia-earnings-fed-minutes"}, {"portal": "The Weekend Spread", "url": "https://theweekendspread.substack.com/p/the-close-thursday-november-19-2026"}]'::jsonb),
  ('2026-11-21', '2026-11-21T09:15:00-03:00', 'El viernes fue una de las peores ruedas del año: el riesgo país saltó a 1.070 puntos, los bonos en dólares cayeron 4,6% y el dólar oficial tocó récord en $1.580 mayorista, mientras Wall Street entró en corrección con el S&P 500 cayendo 3,7%. Al golpe de afuera se suman dudas propias por los vencimientos de enero y de 2027, un BCRA que dejó de comprar dólares y una brecha con el contado con liquidación que ya roza el 13%. El dato a mirar esta semana es la licitación del Tesoro del 26 de noviembre, que tiene que renovar cerca de $20 billones, junto con el tratamiento del Presupuesto en Diputados.', '{"explicacion": "Pesa más lo local: el salto del riesgo país, la presión sobre el dólar y el freno de las compras del BCRA son parte de un mismo cuadro de desconfianza hacia 2027, así que se cuentan una sola vez. Lo global resta por la corrección de Wall Street y una Fed que sigue pensando en subir tasas, aunque la baja de los rendimientos del Tesoro el viernes amortigua algo.", "factorAR": -0.8, "factorGlobal": -0.5}'::jsonb, '[{"ajustes": {"soberanos": -0.05}, "ambito": "Argentina", "canal": "Baja directamente el precio de los bonos soberanos en dólares y encarece el financiamiento de empresas y provincias.", "confianza": "alta", "factorAR": -0.5, "factorGlobal": -0.1, "fuente": "Infobae", "horizonte": "semanas", "id": "riesgo-pais-1070", "resumen": "El riesgo país subió 135 puntos (+14,3%) a 1.070 pb el 20/11; Globales y Bonares cayeron 4,6% en promedio y acumulan -18% en 2026. Analistas lo atribuyen a los vencimientos de 2027, la incertidumbre electoral y la caída de Wall Street.", "titulo": "El riesgo país saltó 14% en un día y llegó a 1.070 puntos, máximo desde las elecciones de 2025", "url": "https://www.infobae.com/economia/2026/11/20/el-riesgo-pais-salto-14-en-un-solo-dia-y-alcanzo-el-nivel-mas-alto-desde-las-elecciones-de-2025/"}, {"ajustes": {"mep": 0.05, "pesos": -0.05}, "ambito": "Argentina", "canal": "Erosiona en dólares las posiciones en pesos y sube el valor de cobertura del MEP y CCL; menos compras del BCRA dejan menos colchón para pagar deuda.", "confianza": "alta", "factorAR": -0.3, "factorGlobal": 0, "fuente": "iProfesional", "horizonte": "semanas", "id": "dolar-record-brecha", "resumen": "El 19/11 el mayorista cerró en $1.565 y el CCL superó $1.730; el BCRA compró solo US$11 millones y las reservas bajaron a US$49.551 millones. En enero vencen unos US$4.400 millones de Bonares y Globales.", "titulo": "Dólar oficial en récord y brecha con el CCL arriba del 10%: el BCRA frenó sus compras", "url": "https://www.iprofesional.com/economia/469549-el-dolar-oficial-supero-los-1560-y-la-brecha-con-el-financiero-se-mantuvo-en-10"}, {"ajustes": {"merval": -0.05}, "ambito": "Argentina", "canal": "Golpea a las acciones locales, sobre todo bancos, por menor crédito y mayor riesgo; un avance legislativo podría aliviar.", "confianza": "media", "factorAR": -0.2, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "merval-bancos-semana", "resumen": "El MSCI Merval acumula -20% en noviembre y -40% desde julio; Supervielle cayó 22,6% en la semana tras un balance flojo. La TIR del AL30 subió a 16,94%; la semana que viene se tratan el Presupuesto y la suspensión de las PASO.", "titulo": "El Merval cayó cerca de 10% en dólares en la semana y los bancos lideraron las pérdidas", "url": "https://www.ambito.com/finanzas/los-bonos-dolares-se-desploman-wall-street-y-aumenta-la-presion-el-riesgo-pais-n6347533"}, {"ajustes": {"cedears": -0.05}, "ambito": "Mundo", "canal": "Baja directamente los CEDEARs, en especial tecnológicos, y reduce el apetito por riesgo emergente.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.5, "fuente": "Yahoo Finance / The Motley Fool", "horizonte": "semanas", "id": "wall-street-correccion-ia", "resumen": "El 20/11 el S&P 500 cerró en 6.910 (-3,7%), el Nasdaq en 22.618 (-5,28%, negativo en el año) y el VIX en 35,9; Nvidia cayó 14% por reportes de una investigación contable. El bono a 10 años bajó a 4,91%.", "titulo": "Wall Street entra en corrección: el S&P 500 cayó 3,7% y Nvidia 14% por una revisión de la SEC", "url": "https://finance.yahoo.com/markets/stocks/articles/stock-market-today-nov-20-223513707.html"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. presionan a bonos emergentes y a las acciones de crecimiento.", "confianza": "media", "factorAR": -0.1, "factorGlobal": -0.2, "fuente": "Finimize (Reuters)", "horizonte": "semanas", "id": "fed-suba-diciembre", "resumen": "Tras dichos de Waller, los futuros implicaban ~95% de probabilidad de una suba de 0,25 punto en diciembre; el 10 años estaba en 5,07% el 18/11. El PCE de octubre sale el 25/11.", "titulo": "El mercado da 95% de chances a una suba de tasas de la Fed el 8-9 de diciembre", "url": "https://finimize.com/content/wallers-hawkish-talk-kept-treasury-yields-from-falling-further"}, {"ajustes": {"pesos": -0.03}, "ambito": "Mundo", "canal": "Un real débil abarata a Brasil frente a Argentina y suma presión sobre el peso y las exportadoras locales.", "confianza": "media", "factorAR": -0.15, "factorGlobal": -0.05, "fuente": "The Rio Times", "horizonte": "semanas", "id": "real-brasil-debil", "resumen": "La PTAX pasó de R$4,97 el 6/10 a R$5,81 el 18/11 y el viernes el dólar llegó a R$5,95, máximo desde enero de 2025; pesan el dólar global fuerte y la baja del petróleo y el mineral de hierro.", "titulo": "El real brasileño perdió más de 14% desde octubre y tocó 5,95 por dólar", "url": "https://www.riotimesonline.com/brazil-real-weakens-oil-iron-ore-slide/"}]'::jsonb, '[{"descripcion": "Wall Street estabiliza tras caer más de 10% desde el récord y el Gobierno aprueba Presupuesto y renueva bien la licitación del 26/11, devolviendo el riesgo país desde 1.070 hacia 850 pb.", "dolar": 2, "id": "alivio-rebote", "nombre": "Rebote con alivio", "petroleo": 0, "prob": 20, "riesgoPais": -200, "senales": ["Rollover de la licitación del 26/11 por encima de 100%", "BCRA vuelve a comprar más de US$50 millones diarios"], "spx": 6, "tasas": -15}, {"descripcion": "Los mercados quedan volátiles sin nuevo derrumbe; el riesgo país oscila entre 950 y 1.100 pb y el mayorista sube gradualmente desde $1.580, lejos del techo de banda de $1.974.", "dolar": 4, "id": "tension-contenida", "nombre": "Tensión contenida", "petroleo": -3, "prob": 35, "riesgoPais": -50, "senales": ["VIX se mantiene entre 25 y 35", "Brecha CCL-mayorista estable alrededor de 13%"], "spx": 0, "tasas": 10}, {"descripcion": "Licitación floja y dudas sobre el pago de US$4.400 millones de enero empujan el riesgo país arriba de 1.300 pb y el dólar oficial hacia $1.750.", "dolar": 12, "id": "estres-local", "nombre": "Estrés local", "petroleo": -5, "prob": 20, "riesgoPais": 300, "senales": ["Rollover de la licitación por debajo de 85%", "Reservas brutas por debajo de US$48.000 millones"], "spx": -3, "tasas": 15}, {"descripcion": "La venta de acciones de IA se contagia al crédito corporativo y el S&P 500 cae hacia 6.100 desde 6.910; las tasas del Tesoro bajan por refugio y la Fed duda de subir.", "dolar": 8, "id": "crash-ia", "nombre": "Crash tecnológico global", "petroleo": -12, "prob": 15, "riesgoPais": 200, "senales": ["Nasdaq-100 cierra más de 20% abajo de su máximo", "Spreads de bonos corporativos high yield se amplían con fuerza"], "spx": -12, "tasas": -40}, {"descripcion": "Un PCE caliente el 25/11 y un buen empleo el 4/12 llevan a la Fed a subir 0,50 punto en diciembre, con el 10 años de vuelta arriba de 5,2%.", "dolar": 6, "id": "fed-agresiva", "nombre": "Fed más dura", "petroleo": -2, "prob": 10, "riesgoPais": 100, "senales": ["PCE núcleo de octubre cerca de 0,4% mensual", "Futuros asignan más de 30% a una suba de 0,50 punto"], "spx": -6, "tasas": 40}]'::jsonb, '[{"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/20/el-riesgo-pais-salto-14-en-un-solo-dia-y-alcanzo-el-nivel-mas-alto-desde-las-elecciones-de-2025/"}, {"portal": "iProfesional", "url": "https://www.iprofesional.com/economia/469549-el-dolar-oficial-supero-los-1560-y-la-brecha-con-el-financiero-se-mantuvo-en-10"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/los-bonos-dolares-se-desploman-wall-street-y-aumenta-la-presion-el-riesgo-pais-n6347533"}, {"portal": "Yahoo Finance / The Motley Fool", "url": "https://finance.yahoo.com/markets/stocks/articles/stock-market-today-nov-20-223513707.html"}, {"portal": "Finimize (Reuters)", "url": "https://finimize.com/content/wallers-hawkish-talk-kept-treasury-yields-from-falling-further"}, {"portal": "The Rio Times", "url": "https://www.riotimesonline.com/brazil-real-weakens-oil-iron-ore-slide/"}]'::jsonb),
  ('2026-11-22', '2026-11-22T08:50:00-03:00', 'La semana cerró con un golpe doble: Wall Street entró en corrección (S&P 500 -8,6% en la semana) y el riesgo país pasó los 1.000 puntos por primera vez desde octubre de 2025, mientras el dólar mayorista tocó un récord de $1.580 y el BCRA dejó de comprar. A eso se suman la devaluación del real y la presión de la Fed, que debate subir la tasa 0,5 punto en diciembre. El dato a mirar mañana es si el riesgo país logra volver debajo de 1.000 con la apertura de Wall Street, y el miércoles 26, cuánto renueva el Tesoro en su licitación.', '{"explicacion": "El tono es claramente negativo en los dos frentes. Buena parte de la caída argentina se explica por el mismo shock global (venta de tecnológicas y Fed más dura), así que no se suma entero: el factor local agrega encima lo propio (reservas que no crecen, dólar en récord, real débil y dudas sobre 2027), y lo compensa en parte la chance de que el Congreso apruebe Presupuesto y suspensión de las PASO.", "factorAR": -0.55, "factorGlobal": -0.45}'::jsonb, '[{"ajustes": {"soberanos": -0.05}, "ambito": "Argentina", "canal": "Baja directamente el precio de bonos soberanos y acciones locales y encarece el financiamiento de empresas y del Tesoro.", "confianza": "alta", "factorAR": -0.4, "factorGlobal": -0.05, "fuente": "Ámbito", "horizonte": "semanas", "id": "riesgo-pais-supera-1000", "resumen": "El índice de JP Morgan pasó de 832 a 1.071 puntos en la semana; los Globales cayeron 4% y los Bonares 5%, con la TIR del AL30 en 16,94%. El MSCI Merval perdió cerca de 10% en dólares en cinco ruedas y 20% en noviembre.", "titulo": "El riesgo país saltó 29% en la semana y superó los 1.000 puntos por primera vez desde octubre de 2025", "url": "https://www.ambito.com/finanzas/los-bonos-dolares-se-desploman-wall-street-y-aumenta-la-presion-el-riesgo-pais-n6347533"}, {"ajustes": {"cer": -0.03, "pesos": -0.05}, "ambito": "Argentina", "canal": "Un dólar más caro y menos reservas restan valor en dólares a los activos en pesos y suben la duda sobre los pagos de deuda.", "confianza": "media", "factorAR": -0.3, "factorGlobal": 0, "fuente": "BAE Negocios", "horizonte": "semanas", "id": "dolar-record-bcra-sin-compras", "resumen": "El mayorista subió $36,50 en la semana, la mayor suba desde junio; el BCRA compró USD 331 millones en noviembre contra USD 1.395 millones en octubre y las reservas brutas quedaron en USD 49.443 millones. En enero vencen unos USD 4.500 millones.", "titulo": "Dólar mayorista en récord de $1.580 y el BCRA cortó nueve ruedas seguidas de compras", "url": "https://www.baenegocios.com/finanzas/el-bcra-freno-las-compras-de-dolares-tras-nueve-ruedas-consecutivas-y-quedo-bajo-presion/"}, {"ajustes": {"cedears": -0.03}, "ambito": "Mundo", "canal": "Pega de lleno en los CEDEARs y, por aversión al riesgo, arrastra a bonos y acciones de emergentes como Argentina.", "confianza": "media", "factorAR": -0.15, "factorGlobal": -0.5, "fuente": "Investrade (Hammerstone Markets)", "horizonte": "semanas", "id": "wall-street-correccion-ia", "resumen": "El S&P 500 cerró en 6.910 (-8,6% semanal) y el Nasdaq perdió 10% en la semana; Nvidia acumula casi -50% desde su máximo y el VIX subió a 37,4. El bono a 10 años bajó a 4,91% por búsqueda de refugio.", "titulo": "El S&P 500 cayó 3,7% el viernes, entró en corrección y cerró su peor semana desde abril de 2025", "url": "https://investrade.com/market-review-november-20-2026/"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. fortalecen el dólar global, restan atractivo a emergentes y pesan sobre las tecnológicas.", "confianza": "media", "factorAR": -0.1, "factorGlobal": -0.25, "fuente": "Yahoo Finance (Decrypt)", "horizonte": "semanas", "id": "fed-suba-50-diciembre", "resumen": "Con la inflación núcleo subiendo 0,3% mensual por tercer mes, Waller propuso llevar la tasa de 3,75%-4% a 4,25%-4,50%; los futuros daban ~95% a una suba de 0,25 y ~5% a una de 0,5.", "titulo": "Waller pide subir la tasa 0,5 punto en la reunión de la Fed del 8 y 9 de diciembre", "url": "https://finance.yahoo.com/news/feds-waller-calls-50-basis-181602048.html"}, {"ajustes": {"pesos": -0.03}, "ambito": "Mundo", "canal": "Encarece a la Argentina frente a su principal socio, presiona al dólar local y a las empresas que exportan a Brasil.", "confianza": "media", "factorAR": -0.2, "factorGlobal": -0.05, "fuente": "The Rio Times", "horizonte": "meses", "id": "real-brasil-devaluacion", "resumen": "La tasa PTAX pasó de R$4,97 a R$5,81 entre el 6 de octubre y el 18 de noviembre, el real más débil desde abril de 2025, con petróleo y mineral de hierro en baja. Brasil pesa 27,2% en el tipo de cambio real multilateral argentino.", "titulo": "El real perdió cerca de 14,5% desde el 6 de octubre y el dólar llegó a R$5,81 en Brasil", "url": "https://www.riotimesonline.com/brazil-real-weakens-oil-iron-ore-slide/"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Si se aprueban, bajan la incertidumbre política y podrían aliviar parte del castigo a bonos y dólar.", "confianza": "baja", "factorAR": 0.15, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "paso-presupuesto-congreso", "resumen": "El oficialismo consiguió dictamen en el Senado para suspender las PASO; los analistas consultados ven un efecto levemente positivo pero acotado frente a reservas, deuda y el pago de enero. El calendario electoral 2027 arranca el 14 de febrero en Neuquén.", "titulo": "Semana clave en el Congreso: Presupuesto en Diputados y suspensión de las PASO en el Senado", "url": "https://www.ambito.com/finanzas/suspension-las-paso-que-impacto-espera-el-mercado-el-dolar-y-los-bonos-si-se-aprueba-el-proyecto-n6347081"}, {"ajustes": {"merval": -0.03, "ons": -0.02}, "ambito": "Mundo", "canal": "Un crudo más barato reduce ingresos de YPF y de las energéticas de Vaca Muerta que pesan en el Merval y en las ON.", "confianza": "baja", "factorAR": -0.05, "factorGlobal": 0.05, "fuente": "Investrade (Hammerstone Markets)", "horizonte": "semanas", "id": "petroleo-tercera-baja", "resumen": "El Brent subió 0,64% el viernes pero cerró la semana en baja por fuertes exportaciones de Medio Oriente, pese a ataques de los hutíes en Riad y a tanqueros en Ormuz. El WTI cerró en US$83,98.", "titulo": "El Brent cerró en US$92,57 y sumó su tercera caída semanal antes de la reunión de la OPEP+", "url": "https://investrade.com/market-review-november-20-2026/"}]'::jsonb, '[{"descripcion": "Wall Street recupera parte de la caída desde 6.910 y el riesgo país vuelve hacia 850 puntos, cerca del cierre del 13 de noviembre (832).", "dolar": 2, "id": "rebote-alivio", "nombre": "Rebote y alivio", "petroleo": 0, "prob": 20, "riesgoPais": -200, "senales": ["El VIX baja de 25 desde 37,4", "La licitación del Tesoro del 26 de noviembre renueva más del 100% de los vencimientos"], "spx": 6, "tasas": -15}, {"descripcion": "Los mercados se estabilizan sin rebotar: el riesgo país oscila entre 950 y 1.100 puntos y el mayorista sube despacio desde $1.580.", "dolar": 4, "id": "tension-contenida", "nombre": "Tensión contenida", "petroleo": -3, "prob": 35, "riesgoPais": 50, "senales": ["El BCRA vuelve a comprar montos chicos en el MLC", "El S&P 500 se mueve en rango 6.700-7.100"], "spx": -2, "tasas": 10}, {"descripcion": "La Fed lleva la tasa de 3,75%-4% a 4,25%-4,50% el 9 de diciembre, el dólar global se fortalece y los emergentes vuelven a caer.", "dolar": 6, "id": "fed-sube-50", "nombre": "Fed sube 0,5 punto", "petroleo": -5, "prob": 15, "riesgoPais": 150, "senales": ["Los futuros de la CME suben la probabilidad de 0,5 punto muy por encima del 5%", "El dato de inflación PCE de EE.UU. vuelve a sorprender al alza"], "spx": -8, "tasas": 40}, {"descripcion": "Las reservas (USD 49.443 millones) caen ante el pago de USD 4.500 millones de enero, la brecha con el CCL (~13%) se amplía y el dólar oficial se acelera.", "dolar": 15, "id": "estres-cambiario-local", "nombre": "Estrés cambiario local", "petroleo": -5, "prob": 15, "riesgoPais": 400, "senales": ["La brecha entre CCL y mayorista supera 20%", "El Tesoro renueva bastante menos del 90% en la licitación y el BCRA vende dólares"], "spx": -3, "tasas": 0}, {"descripcion": "La corrección tecnológica (Nasdaq -10% en la semana) se contagia al crédito corporativo y lleva al S&P 500 hacia 5.700.", "dolar": 8, "id": "crisis-ia-global", "nombre": "Crisis global por la IA", "petroleo": -15, "prob": 10, "riesgoPais": 300, "senales": ["Se amplían los diferenciales de bonos corporativos de alto rendimiento", "Nuevas caídas de Nvidia por la investigación de la SEC"], "spx": -18, "tasas": -40}, {"descripcion": "Diputados aprueba el Presupuesto y el Senado la suspensión de las PASO, lo que recorta la prima política aunque Wall Street siga débil.", "dolar": 2, "id": "congreso-destraba", "nombre": "Congreso destraba", "petroleo": 0, "prob": 5, "riesgoPais": -100, "senales": ["Media sanción del Presupuesto esta semana", "Votación favorable de la suspensión de las PASO en el Senado"], "spx": 0, "tasas": 0}]'::jsonb, '[{"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/los-bonos-dolares-se-desploman-wall-street-y-aumenta-la-presion-el-riesgo-pais-n6347533"}, {"portal": "BAE Negocios", "url": "https://www.baenegocios.com/finanzas/el-bcra-freno-las-compras-de-dolares-tras-nueve-ruedas-consecutivas-y-quedo-bajo-presion/"}, {"portal": "Investrade (Hammerstone Markets)", "url": "https://investrade.com/market-review-november-20-2026/"}, {"portal": "Yahoo Finance (Decrypt)", "url": "https://finance.yahoo.com/news/feds-waller-calls-50-basis-181602048.html"}, {"portal": "The Rio Times", "url": "https://www.riotimesonline.com/brazil-real-weakens-oil-iron-ore-slide/"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/suspension-las-paso-que-impacto-espera-el-mercado-el-dolar-y-los-bonos-si-se-aprueba-el-proyecto-n6347081"}]'::jsonb),
  ('2026-11-23', '2026-11-23T08:50:00-03:00', 'El riesgo país cerró el viernes en 1.070 puntos, el más alto en 13 meses, por una mezcla de derrumbe global de las bolsas (el S&P 500 perdió 8,6% en la semana) y dudas sobre la reelección y el financiamiento de 2027. Hoy los futuros de Wall Street rebotan entre 2% y 3%, pero el dólar mayorista ($1.580) y el CCL (cerca de $1.800) siguen bajo presión, con una brecha que ronda el 14%. El dato a mirar hoy es si el rebote de afuera frena la caída de los bonos; en la semana pesan el EMAE del martes, la inflación PCE de EE.UU. del miércoles y la licitación del Tesoro del jueves 26.', '{"explicacion": "El tono es claramente negativo para Argentina: el salto del riesgo país, la caída en la probabilidad de reelección y el faltante de financiamiento son en buena parte el mismo hecho visto desde distintos ángulos, así que no se suman uno por uno. En lo global, la corrección de Wall Street y la Fed que se encamina a subir tasas pesan más que el rebote de los futuros de hoy, que todavía es frágil.", "factorAR": -0.6, "factorGlobal": -0.25}'::jsonb, '[{"ajustes": {"soberanos": -0.05}, "ambito": "Argentina", "canal": "Baja directamente el precio de los bonos en dólares y encarece el financiamiento de empresas, lo que arrastra a ONs y acciones locales.", "confianza": "alta", "factorAR": -0.35, "factorGlobal": -0.05, "fuente": "Perfil", "horizonte": "semanas", "id": "riesgo-pais-1070", "resumen": "El EMBI de JP Morgan llegó a 1.071 pb con Globales cayendo más de 3% y Bonares hasta 2,8%; el mayorista subió 2,4% en la semana a $1.580 y el CCL 2,2% a $1.782.", "titulo": "El riesgo país saltó 14% el viernes, superó los 1.070 puntos y tocó su máximo en 13 meses", "url": "https://www.perfil.com/economia/el-riesgo-pais-llego-a-los-1.071-puntos-el-nivel-mas-alto-en-13-meses-y-el-dolar-toco-los-1600-aVCyg1j6EV7k"}, {"ajustes": {"pesos": -0.05}, "ambito": "Argentina", "canal": "El riesgo político de 2027 golpea más a los bonos que vencen después de la elección y empuja la dolarización de carteras, presionando al peso.", "confianza": "media", "factorAR": -0.3, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "meses", "id": "reeleccion-35-ccl", "resumen": "En julio los precios de los bonos reflejaban cerca de 90% de chances de reelección; hoy 35%. El CCL saltó 3,2% el viernes hasta $1.800 y la brecha con el mayorista llega a 12,2%.", "titulo": "Los bonos ya asignan 35% a la reelección de Milei y el CCL subió 12% en tres ruedas", "url": "https://www.infobae.com/economia/2026/11/21/menos-confianza-en-la-reeleccion-y-mas-demanda-de-dolares-las-senales-que-inquietan-al-mercado-y-disparan-el-riesgo-pais/"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Si el mercado duda de cómo se pagan los vencimientos de 2027, exige más tasa a toda la curva y castiga a las acciones bancarias.", "confianza": "media", "factorAR": -0.25, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "meses", "id": "ft-faltante-financiamiento", "resumen": "El Tesoro debe cubrir cerca de USD 17.000 millones con privados y la suba de tasas dejó un faltante de unos USD 10.000 millones; desde agosto están suspendidas las emisiones en dólares bajo ley local.", "titulo": "Financial Times: faltan unos USD 10.000 millones para cubrir vencimientos y la economía estaría en recesión técnica", "url": "https://www.infobae.com/economia/2026/11/22/el-financial-times-destaco-el-desafio-financiero-y-electoral-de-milei-por-la-suba-del-riesgo-pais-y-la-recesion-de-la-economia/"}, {"ajustes": {"cer": 0.03, "pesos": -0.05}, "ambito": "Argentina", "canal": "Una renovación baja o a tasas más altas presionaría al dólar y a los bonos en pesos; una buena licitación daría aire de corto plazo.", "confianza": "media", "factorAR": -0.15, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "días", "id": "senales-city-licitacion", "resumen": "Los Globales perdieron entre 5,6% y 8,2% en la semana; el BCRA quedó fuera del mercado de contado el viernes, la brecha rozó 14% y el EMAE de septiembre sale el martes. Los vencimientos de enero rondan USD 4.500 millones.", "titulo": "La city mira la licitación del jueves 26 por $25,4 billones y si el BCRA vuelve a comprar dólares", "url": "https://www.ambito.com/finanzas/la-tormenta-global-desnuda-la-fragilidad-argentina-hasta-cuando-seguira-la-sangria-y-que-senales-espera-la-city-n6348063"}, {"ajustes": {"cedears": -0.05}, "ambito": "Mundo", "canal": "Pega de lleno en los CEDEARs tecnológicos y, por aversión al riesgo, en la deuda emergente y las acciones argentinas.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.4, "fuente": "Investopedia / Yahoo Finance", "horizonte": "semanas", "id": "wall-street-correccion", "resumen": "El S&P 500 cayó 3,7% el viernes a 6.910 (−8,6% semanal) y el Nasdaq −10% semanal; Nvidia perdió 14% en el día y el VIX cerró cerca de 36. El bono a 10 años bajó a 4,94%.", "titulo": "El S&P 500 y el Dow entran en corrección: peor semana desde abril de 2025 por el derrumbe del negocio de la IA", "url": "https://finance.yahoo.com/markets/stocks/articles/stock-market-today-futures-plunge-131303598.html"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Un rebote sostenido aliviaría a los CEDEARs y podría dar un respiro a los bonos argentinos, pero los analistas advierten que puede ser solo técnico.", "confianza": "baja", "factorAR": 0.05, "factorGlobal": 0.2, "fuente": "Business Insider / Yahoo Finance", "horizonte": "días", "id": "futuros-rebote-lunes", "resumen": "Los futuros del Nasdaq subían 3% y los del S&P 500 2%, aunque Asia siguió cayendo (Kospi −3%) y Taiwán y Corea tomaron medidas para estabilizar sus bolsas.", "titulo": "Los futuros de Wall Street rebotan hasta 3% el lunes y Nvidia sube cerca de 9% antes de la apertura", "url": "https://uk.finance.yahoo.com/news/us-stock-futures-rebound-asian-053459216.html"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. y un dólar fuerte drenan fondos de emergentes, suben el piso del riesgo país y presionan las valuaciones de acciones.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.2, "fuente": "FXEmpire", "horizonte": "semanas", "id": "fed-suba-pce", "resumen": "La tasa está en 3,75%-4% y el mercado espera llevarla a 4%-4,25% el 9 de diciembre; el PCE de septiembre fue 3,6% (núcleo 3,1%) y el de octubre sale el 25 de noviembre. El índice dólar está cerca de máximos desde abril de 2025.", "titulo": "La Fed se encamina a subir 25 pb en diciembre y el PCE del miércoles define si serán más", "url": "https://www.fxempire.com/forecasts/article/interest-rate-forecast-december-fed-hike-bets-support-us-dollar-1646310"}, {"ajustes": {"merval": -0.02}, "ambito": "Mundo", "canal": "Un real débil presiona al tipo de cambio argentino y a la competitividad exportadora, y suma ruido a la deuda emergente de la región.", "confianza": "media", "factorAR": -0.15, "factorGlobal": -0.05, "fuente": "The Rio Times", "horizonte": "semanas", "id": "real-brasil-debil", "resumen": "El PTAX pasó de R$4,97 el 6 de octubre a R$5,81 el 18 de noviembre, su nivel más débil desde abril de 2025, con petróleo y mineral de hierro en baja; Copom y Fed deciden el 8-9 de diciembre.", "titulo": "El real perdió más de 14% desde octubre y abarata a Brasil frente a la Argentina", "url": "https://www.riotimesonline.com/brazil-real-weakens-oil-iron-ore-slide/"}]'::jsonb, '[{"descripcion": "Wall Street recupera parte de la corrección (S&P desde 6.910) y el PCE sale tibio; el riesgo país vuelve desde 1.070 hacia la zona de 850-900.", "dolar": 2, "id": "alivio-global", "nombre": "Alivio global y rebote", "petroleo": -3, "prob": 20, "riesgoPais": -200, "senales": ["El S&P 500 vuelve a cerrar arriba de 7.200", "El riesgo país baja de 950 puntos con Globales en alza"], "spx": 6, "tasas": -15}, {"descripcion": "La Fed sube 25 pb a 4%-4,25%, las bolsas se estabilizan y el riesgo país oscila entre 950 y 1.100; el mayorista se desliza de $1.580 hacia $1.640.", "dolar": 4, "id": "base-tension", "nombre": "Base: calma tensa", "petroleo": -2, "prob": 35, "riesgoPais": -50, "senales": ["La licitación del 26/11 renueva cerca o arriba de 100%", "El BCRA vuelve a comprar dólares varias ruedas seguidas"], "spx": 1, "tasas": 10}, {"descripcion": "Sin un anuncio concreto para los USD 4.500 millones de enero, los bonos siguen cayendo, el CCL pasa de $1.800 a más de $2.000 y la brecha supera 20%.", "dolar": 12, "id": "estres-local", "nombre": "Estrés local por financiamiento", "petroleo": 0, "prob": 20, "riesgoPais": 350, "senales": ["Rollover bajo o tasas más altas en la licitación del Tesoro", "Brecha CCL-mayorista por encima de 20%"], "spx": -1, "tasas": 10}, {"descripcion": "El Nasdaq entra en mercado bajista, el PCE sale caliente (septiembre fue 3,6%) y la Fed sube 50 pb; el VIX, hoy cerca de 36, pasa de 40.", "dolar": 8, "id": "bajista-ia-fed", "nombre": "Bajista global: IA + Fed dura", "petroleo": -10, "prob": 15, "riesgoPais": 250, "senales": ["PCE de octubre por encima de 3,8%", "El S&P 500 cierra debajo de 6.500"], "spx": -12, "tasas": 40}, {"descripcion": "Un ataque a infraestructura saudí o en Ormuz revierte el exceso de oferta y el Brent pasa de USD 92,57 a más de USD 110, reavivando la inflación global.", "dolar": 5, "id": "shock-petrolero", "nombre": "Shock petrolero en el Golfo", "petroleo": 20, "prob": 10, "riesgoPais": 80, "senales": ["Incidente sobre exportaciones saudíes por el Mar Rojo", "La OPEP+ recorta cuotas en su reunión del 29/11"], "spx": -5, "tasas": 20}]'::jsonb, '[{"portal": "Perfil", "url": "https://www.perfil.com/economia/el-riesgo-pais-llego-a-los-1.071-puntos-el-nivel-mas-alto-en-13-meses-y-el-dolar-toco-los-1600-aVCyg1j6EV7k"}, {"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/21/menos-confianza-en-la-reeleccion-y-mas-demanda-de-dolares-las-senales-que-inquietan-al-mercado-y-disparan-el-riesgo-pais/"}, {"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/22/el-financial-times-destaco-el-desafio-financiero-y-electoral-de-milei-por-la-suba-del-riesgo-pais-y-la-recesion-de-la-economia/"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/la-tormenta-global-desnuda-la-fragilidad-argentina-hasta-cuando-seguira-la-sangria-y-que-senales-espera-la-city-n6348063"}, {"portal": "Investopedia / Yahoo Finance", "url": "https://finance.yahoo.com/markets/stocks/articles/stock-market-today-futures-plunge-131303598.html"}, {"portal": "Business Insider / Yahoo Finance", "url": "https://uk.finance.yahoo.com/news/us-stock-futures-rebound-asian-053459216.html"}, {"portal": "FXEmpire", "url": "https://www.fxempire.com/forecasts/article/interest-rate-forecast-december-fed-hike-bets-support-us-dollar-1646310"}, {"portal": "The Rio Times", "url": "https://www.riotimesonline.com/brazil-real-weakens-oil-iron-ore-slide/"}]'::jsonb),
  ('2026-11-24', '2026-11-24T08:55:00-03:00', 'El riesgo país pasó los 1.000 puntos el viernes por las dudas sobre cómo se pagan los US$4.400 millones de enero y por el ruido electoral de 2027, y el lunes aflojó a unos 1.020 gracias al rebote de Wall Street. Hoy vuelve a operar la plaza local después del feriado y el dato a mirar es el dólar: el mayorista cerró el viernes en $1.580 y la brecha con el CCL rondó el 14%, así que importa si se calma o sigue subiendo. Afuera, la Reserva Federal se encamina a subir la tasa en diciembre y el miércoles sale la inflación PCE de Estados Unidos, que puede decidir si el rebote de las bolsas se sostiene.', '{"explicacion": "Pesa más lo local: el riesgo país arriba de 1.000, la caja chica del Tesoro frente al pago de enero, la suba del dólar y la inflación de octubre más alta de lo esperado empujan el factor argentino hacia abajo; el rebote del lunes y una posible suspensión de las PASO compensan solo en parte. En el mundo, el rebote de Wall Street por Nvidia se cruza con una Fed que va a subir tasas y con la debilidad del real brasileño, por lo que el factor global queda casi neutro. No se suman uno por uno: la caída del viernes y el rebote del lunes son parte del mismo episodio.", "factorAR": -0.45, "factorGlobal": -0.05}'::jsonb, '[{"ajustes": {}, "ambito": "Argentina", "canal": "Un riesgo país arriba de 1.000 baja el precio de los bonos en dólares y de las acciones locales, y encarece cualquier refinanciación del Estado y las empresas.", "confianza": "alta", "factorAR": -0.3, "factorGlobal": 0, "fuente": "La Nación", "horizonte": "semanas", "id": "riesgo-pais-supera-1000", "resumen": "Tras tocar el viernes su nivel más alto desde las legislativas de 2025, el riesgo país bajó 49 puntos a 1.021 el lunes y los ADR subieron hasta 6%. Aun así, en las primeras tres semanas de noviembre el indicador subió 29,7%.", "titulo": "El riesgo país superó los 1.000 puntos y el lunes retrocedió a 1.021 con el rebote externo", "url": "https://www.lanacion.com.ar/economia/dolar/cae-el-riesgo-pais-wall-street-rebota-con-fuerza-y-contagia-a-las-acciones-argentinas-que-cotizan-en-nid23112026/"}, {"ajustes": {"mep": 0.05, "pesos": -0.05}, "ambito": "Argentina", "canal": "Un dólar que sube rápido erosiona las colocaciones en pesos medidas en dólares y presiona la inflación, mientras que lo dolarizado (MEP) funciona como cobertura.", "confianza": "alta", "factorAR": -0.3, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "dolar-brecha-14", "resumen": "El viernes el mayorista llegó a $1.580, el minorista superó los $1.600, el MEP rozó $1.680 y el CCL casi $1.800. El BCRA no compró dólares después de nueve ruedas seguidas con saldo positivo.", "titulo": "El dólar oficial tuvo su mayor suba semanal en 19 meses y la brecha con el CCL rozó el 14%", "url": "https://www.ambito.com/finanzas/dolar-hoy-y-dolar-blue-hoy-minuto-minuto-cuanto-opera-este-viernes-20-noviembre-n6347436"}, {"ajustes": {"soberanos": -0.05}, "ambito": "Argentina", "canal": "Mientras no se sepa de dónde salen los dólares para enero, los bonos soberanos cargan una prima extra y el mercado castiga más los tramos cortos.", "confianza": "media", "factorAR": -0.35, "factorGlobal": 0, "fuente": "La Política Online", "horizonte": "meses", "id": "vencimiento-enero-tesoro", "resumen": "Según Fortress, la diferencia es de US$3.570 millones; GMA Capital calcula vencimientos de Bonares y Globales por US$12.242 millones en 2027 y CEPA estima un agujero de US$5.000 millones en el programa financiero.", "titulo": "El Tesoro tendría US$830 millones para pagar unos US$4.400 millones de bonos en enero", "url": "https://www.lapoliticaonline.com/economia/caputo-tiene-apenas-usd-830-millones-para-pagar-vencimientos-por-usd-4-400-millones-en-enero/"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Menos incertidumbre electoral reduce la prima política que hoy pagan bonos y acciones argentinas.", "confianza": "baja", "factorAR": 0.15, "factorGlobal": 0, "fuente": "iProUP", "horizonte": "semanas", "id": "senado-paso", "resumen": "Operadores citados señalan que una aprobación podría mejorar los precios de los activos, aunque de forma limitada; también piden definir cómo se pagará el vencimiento de enero, de unos US$4.500 millones.", "titulo": "El Senado define esta semana la suspensión de las PASO, clave para el mapa electoral de 2027", "url": "https://www.iproup.com/economia-digital/73375-que-acciones-animan-el-rebote-tecnico-de-wall-street"}, {"ajustes": {"cer": 0.05, "pesos": -0.03}, "ambito": "Argentina", "canal": "Más inflación quita atractivo a la tasa fija en pesos y favorece relativamente a los bonos que ajustan por CER.", "confianza": "alta", "factorAR": -0.15, "factorGlobal": 0, "fuente": "Rankia Argentina (datos INDEC)", "horizonte": "semanas", "id": "inflacion-octubre-2-2", "resumen": "La interanual bajó a 33,1% y la acumulada del año llega a 26,3%; la núcleo fue 1,5%. El dato de noviembre se publica el 15 de diciembre.", "titulo": "La inflación de octubre fue 2,2%, la más alta desde abril y por encima del 1,8% que esperaba el REM", "url": "https://www.rankia.com.ar/noticias/bolsa/7550399-inflacion-octubre-2026-ipc-indec-fue-2-mas-alto-abril"}, {"ajustes": {"cedears": 0.05}, "ambito": "Mundo", "canal": "Los CEDEARs siguen de cerca a las bolsas de EE.UU., y un mejor clima global también ayuda a bonos y acciones argentinas.", "confianza": "media", "factorAR": 0.1, "factorGlobal": 0.25, "fuente": "The Glass Desk / Investing.com", "horizonte": "días", "id": "wall-street-nvidia-rebote", "resumen": "En la semana al 20 de noviembre el S&P 500 cayó 8,61% a 6.910 y Nvidia 22,9%; el lunes el índice subió 4,73% a 7.237 y Nvidia 31%. El VIX sigue alto, en torno a 29.", "titulo": "Wall Street rebotó tras su peor semana desde 2025: el S&P 500 subió 4,7% con el regreso de Huang a Nvidia", "url": "https://theglassdesk.substack.com/p/weekly-market-review-nov-20-2026"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. encarecen el financiamiento de emergentes, fortalecen al dólar global y pesan sobre las acciones.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.3, "fuente": "Investing.com", "horizonte": "semanas", "id": "fed-suba-diciembre", "resumen": "Con la tasa en 3,75%-4%, una suba de 25 puntos básicos el 8-9 de diciembre es el escenario base y Waller y Cook pidieron más dureza; el bono a 10 años rinde cerca de 4,89%. El Brent bajó unos 21% desde el pico de octubre, a la zona de US$87.", "titulo": "La Fed se encamina a subir la tasa 0,25 punto en diciembre; el miércoles sale la inflación PCE", "url": "https://www.investing.com/news/stock-market-news/fed-signals-and-data-what-happened-the-week-of-nov-1620-2026-93CH-5042523"}, {"ajustes": {"merval": -0.03}, "ambito": "Mundo", "canal": "Un real débil abarata a Brasil frente a la producción argentina y suma presión regional sobre el peso y los activos locales.", "confianza": "media", "factorAR": -0.15, "factorGlobal": -0.05, "fuente": "The Rio Times", "horizonte": "semanas", "id": "brasil-real-5-91", "resumen": "El Senado aprobó el paquete fiscal, pero el mercado duda de que alcance; el gobierno estima una mejora de US$7.700 a US$9.500 millones en 2027 y la Cámara de Diputados lo votaba el 23 de noviembre.", "titulo": "El real brasileño tocó 5,91 por dólar, su peor nivel en 19 meses, por dudas sobre el ajuste fiscal", "url": "https://www.riotimesonline.com/brazil-dollar-tops-5-90-reais-after-senate-fiscal-vote/"}]'::jsonb, '[{"descripcion": "El Gobierno muestra de dónde salen los cerca de US$4.400 millones de enero y se suspenden las PASO; el riesgo país vuelve desde ~1.020 hacia la zona de 800 y Wall Street consolida el rebote.", "dolar": 2, "id": "alivio-financiero", "nombre": "Alivio con plan de pago", "petroleo": -5, "prob": 20, "riesgoPais": -200, "senales": ["Anuncio concreto de financiamiento (repo, swap u organismos) para el pago del 9 de enero", "Riesgo país cerrando por debajo de 900 puntos"], "spx": 4, "tasas": -15}, {"descripcion": "El riesgo país se queda entre 950 y 1.100 sin definiciones sobre enero, el dólar sigue deslizándose desde $1.580 y la Fed sube 0,25 en diciembre como se espera.", "dolar": 4, "id": "base-volatil", "nombre": "Volatilidad con riesgo país alto", "petroleo": 0, "prob": 35, "riesgoPais": 0, "senales": ["Brecha con el CCL estable entre 10% y 15%", "Suba de 25 puntos básicos de la Fed sin señal de otra en enero"], "spx": 1, "tasas": 10}, {"descripcion": "Sin dólares a la vista para enero y con el BCRA sin comprar, la brecha supera el 20% y el riesgo país vuelve a 1.300 o más desde los 1.070 del viernes.", "dolar": 12, "id": "estres-cambiario", "nombre": "Estrés cambiario local", "petroleo": 0, "prob": 20, "riesgoPais": 350, "senales": ["Mayorista rompiendo con fuerza los $1.650 y CCL arriba de $2.000", "Caída de reservas o uso de fondos del BCRA para pagar deuda sin financiamiento nuevo"], "spx": 0, "tasas": 10}, {"descripcion": "Un PCE alto lleva a la Fed a subir 0,5 en diciembre o anticipar más subas; el S&P 500 pierde el rebote y vuelve debajo de 6.900 con el bono a 10 años arriba de 5%.", "dolar": 6, "id": "fed-agresiva", "nombre": "Fed agresiva y caída global", "petroleo": -8, "prob": 15, "riesgoPais": 150, "senales": ["Inflación PCE de octubre por encima de lo esperado el miércoles", "Probabilidad de suba de 50 puntos básicos en CME FedWatch por encima de 30%"], "spx": -8, "tasas": 40}, {"descripcion": "El paquete fiscal brasileño se traba o se diluye en Diputados y el real pasa de 5,91 a más de 6,2 por dólar, arrastrando monedas y activos de la región.", "dolar": 8, "id": "contagio-brasil", "nombre": "Contagio desde Brasil", "petroleo": -3, "prob": 10, "riesgoPais": 200, "senales": ["Real por encima de 6 por dólar en forma sostenida", "Cambios al proyecto PLP 299/2026 que lo devuelvan al Senado"], "spx": -2, "tasas": 5}]'::jsonb, '[{"portal": "La Nación", "url": "https://www.lanacion.com.ar/economia/dolar/cae-el-riesgo-pais-wall-street-rebota-con-fuerza-y-contagia-a-las-acciones-argentinas-que-cotizan-en-nid23112026/"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/dolar-hoy-y-dolar-blue-hoy-minuto-minuto-cuanto-opera-este-viernes-20-noviembre-n6347436"}, {"portal": "La Política Online", "url": "https://www.lapoliticaonline.com/economia/caputo-tiene-apenas-usd-830-millones-para-pagar-vencimientos-por-usd-4-400-millones-en-enero/"}, {"portal": "iProUP", "url": "https://www.iproup.com/economia-digital/73375-que-acciones-animan-el-rebote-tecnico-de-wall-street"}, {"portal": "Rankia Argentina (datos INDEC)", "url": "https://www.rankia.com.ar/noticias/bolsa/7550399-inflacion-octubre-2026-ipc-indec-fue-2-mas-alto-abril"}, {"portal": "The Glass Desk / Investing.com", "url": "https://theglassdesk.substack.com/p/weekly-market-review-nov-20-2026"}, {"portal": "Investing.com", "url": "https://www.investing.com/news/stock-market-news/fed-signals-and-data-what-happened-the-week-of-nov-1620-2026-93CH-5042523"}, {"portal": "The Rio Times", "url": "https://www.riotimesonline.com/brazil-dollar-tops-5-90-reais-after-senate-fiscal-vote/"}]'::jsonb),
  ('2026-11-25', '2026-11-25T08:50:00-03:00', 'El riesgo país tocó 1.108 puntos, su nivel más alto en más de un año, mientras el dólar oficial, el blue y el contado con liqui marcaron récords y el Banco Central pasó dos ruedas sin comprar dólares. Afuera tampoco ayuda: el mercado da casi por segura una suba de tasas de la Fed en diciembre y Wall Street devolvió parte del rebote del lunes. Hoy el dato a mirar es la inflación PCE y el PIB de Estados Unidos (10:30 de Buenos Aires), y mañana jueves la licitación del Tesoro por $25,4 billones.', '{"explicacion": "Riesgo país, presión cambiaria y caída de reservas son en buena parte el mismo episodio de desconfianza local, así que no se suman uno por uno: en conjunto pesan unos -0,6 a -0,7 desvíos sobre activos argentinos, con la recesión técnica y la licitación del jueves como agravantes. En lo global, la Fed con sesgo de suba y la volatilidad de las tecnológicas restan alrededor de -0,3; el petróleo más barato en el mes compensa poco.", "factorAR": -0.7, "factorGlobal": -0.3}'::jsonb, '[{"ajustes": {"soberanos": -0.03}, "ambito": "Argentina", "canal": "Golpea directo el precio de los bonos soberanos y arrastra a ONs y acciones locales por la mayor tasa exigida a todo lo argentino.", "confianza": "alta", "factorAR": -0.4, "factorGlobal": 0, "fuente": "Perfil", "horizonte": "semanas", "id": "riesgo-pais-1108", "resumen": "El índice de JP Morgan subió más de 7% desde 1.035 pb y llegó a 1.108 pb el martes 24, con una suba de más de 35% en el mes. Pesan las dudas sobre el acceso al crédito, los vencimientos de 2027 y las elecciones presidenciales.", "titulo": "El riesgo país tocó 1.108 puntos, el nivel más alto en más de un año", "url": "https://www.perfil.com/economia/el-riesgo-pais-rompe-la-barrera-de-los-1100-puntos-y-alcanza-el-nivel-mas-alto-del-ano-mientras-el-dolar-oficial-llega-a-1615-a5Q7B3m4Fz5t"}, {"ajustes": {"mep": 0.05, "pesos": -0.05}, "ambito": "Argentina", "canal": "Encarece la cobertura y erosiona en dólares lo que está en pesos; la brecha más ancha favorece relativamente a quien ya tiene MEP.", "confianza": "alta", "factorAR": -0.3, "factorGlobal": 0, "fuente": "El Cronista", "horizonte": "semanas", "id": "dolar-blue-ccl-record", "resumen": "El blue llegó a $1.675 (sube $110 en noviembre) y el CCL operó cerca de $1.850, mientras el mayorista rondaba $1.577, lejos del techo de la banda de $1.976,68. Ámbito informó cierres de $1.593 mayorista y $1.794 CCL, con brecha de 12,6%.", "titulo": "Blue y contado con liqui en récord; el mayorista sigue lejos del techo de la banda", "url": "https://www.cronista.com/finanzas-mercados/dolar-blue-hoy-a-cuanto-cotiza-este-martes-24-de-noviembre-con-el-mep-y-el-ccl/"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Menos reservas debilitan la capacidad de pago percibida y alimentan la presión sobre el dólar y los bonos.", "confianza": "media", "factorAR": -0.25, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "bcra-sin-compras-reservas", "resumen": "Las reservas brutas bajaron a u$s48.744 millones, el menor nivel en más de un mes (u$s230 millones por la caída del oro). Las compras de noviembre quedaron en u$s344 millones y en futuros se operaron u$s1.866 millones por demanda de cobertura.", "titulo": "El BCRA no compró por segunda rueda y las reservas cayeron u$s618 millones", "url": "https://www.ambito.com/finanzas/el-bcra-no-compro-dolares-segunda-rueda-fila-y-las-reservas-cayeron-al-menor-nivel-mas-un-mes-n6348885"}, {"ajustes": {"merval": -0.03}, "ambito": "Argentina", "canal": "Peores ventas y balances para empresas del mercado interno y más ruido político rumbo a 2027; energía y minería aguantan mejor.", "confianza": "alta", "factorAR": -0.15, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "meses", "id": "emae-recesion-tecnica", "resumen": "Según el EMAE del INDEC, la actividad cayó 1,8% en el tercer trimestre contra el segundo y 1,2% interanual en septiembre. Adcap recortó su proyección de crecimiento 2026 de 1,7% a 0,7%; el PIB oficial sale el 16 de diciembre.", "titulo": "La economía entró en recesión técnica pese a crecer 1,1% mensual en septiembre", "url": "https://www.ambito.com/la-economia-entro-recesion-tecnica-sumo-dos-trimestres-seguidos-caida-pese-crecer-11-mensual-septiembre-n6348824"}, {"ajustes": {"cer": -0.03}, "ambito": "Argentina", "canal": "Una renovación baja liberaría pesos que pueden ir al dólar; tasas más altas castigan los bonos en pesos a tasa fija y CER.", "confianza": "media", "factorAR": -0.15, "factorGlobal": 0, "fuente": "Perfil", "horizonte": "días", "id": "licitacion-tesoro-25-billones", "resumen": "Unos $20 billones están en manos privadas; según Wise Capital, las colocaciones de largo plazo cayeron de 42% (marzo-julio) a 5% en la primera licitación de noviembre. Se espera que el Tesoro acorte plazos o convalide tasas más altas.", "titulo": "El Tesoro enfrenta vencimientos por $25,4 billones en la licitación del jueves", "url": "https://www.perfil.com/economia/el-riesgo-pais-rompe-la-barrera-de-los-1100-puntos-y-alcanza-el-nivel-mas-alto-del-ano-mientras-el-dolar-oficial-llega-a-1615-a5Q7B3m4Fz5t"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. restan atractivo a la deuda emergente y presionan las valuaciones de acciones globales y Cedears.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.25, "fuente": "Ámbito", "horizonte": "semanas", "id": "fed-suba-diciembre", "resumen": "Según CME FedWatch, la probabilidad de una suba de 25 pb en diciembre es 97% y la de otra en enero, 66%. El índice dólar bajó 0,47% a 103,81 tras tocar máximos de casi dos años.", "titulo": "El mercado asigna 97% a una suba de tasas de la Fed en diciembre", "url": "https://www.ambito.com/uruguay/el-dolar-global-retrocede-y-wall-street-vuelve-caer-desinflarse-el-repunte-nvidia-n6348521"}, {"ajustes": {"cedears": -0.03}, "ambito": "Mundo", "canal": "Los Cedears tecnológicos siguen muy volátiles; un PCE alto reforzaría la Fed dura y la caída.", "confianza": "media", "factorAR": 0, "factorGlobal": -0.15, "fuente": "StockTitan", "horizonte": "días", "id": "wall-street-nvidia-devuelve", "resumen": "El martes 24 el fondo del S&P 500 cerró -0,49% y el del Nasdaq 100 -1,99%, que había subido 7% el lunes con el regreso de Jensen Huang a Nvidia. Hoy se publican el PIB del tercer trimestre y la inflación PCE de octubre.", "titulo": "Wall Street devolvió parte del rebote: Nvidia cayó 5,9% tras subir 31,5%", "url": "https://www.stocktitan.net/articles/stock-market-today-live-november-24-2026"}, {"ajustes": {"merval": 0.02}, "ambito": "Mundo", "canal": "Un petróleo más bajo resta a las energéticas locales (YPF, Vista) pero alivia la inflación global; una escalada en Ormuz haría lo contrario.", "confianza": "media", "factorAR": 0, "factorGlobal": -0.05, "fuente": "Bloomberg (vía Rigzone)", "horizonte": "semanas", "id": "petroleo-hormuz-opep", "resumen": "El Brent subió 2,3% a US$91,40 tras tocar mínimos de tres meses; el WTI cayó más de un quinto en noviembre. La AIE prevé superávit este trimestre y la OPEP+ se reúne este fin de semana con Irak en disputa por su cuota.", "titulo": "El Brent rebotó a US$91,40 por ataques en Ormuz pese al temor de sobreoferta", "url": "https://www.rigzone.com/news/wire/oil_climbs_despite_growing_oversupply_fears-24-nov-2026-185160-article/"}]'::jsonb, '[{"descripcion": "La licitación se renueva con plazos cortos y tasas algo mayores; el riesgo país oscila entre 1.000 y 1.150 pb y el mayorista sube gradual desde $1.593, lejos del techo de $1.976. La Fed sube 25 pb como se descuenta.", "dolar": 3, "id": "volatilidad-contenida", "nombre": "Volatilidad contenida", "petroleo": -3, "prob": 35, "riesgoPais": 50, "senales": ["Rollover de la licitación del jueves cerca o por encima de 90%", "El BCRA vuelve a comprar dólares en diciembre"], "spx": 0, "tasas": 25}, {"descripcion": "Baja renovación en la licitación y caída de reservas por debajo de u$s48.000 millones empujan el riesgo país hacia 1.400 pb y el CCL por encima de $1.900. La recesión técnica suma ruido político rumbo a 2027.", "dolar": 9, "id": "estres-local", "nombre": "Estrés local", "petroleo": 0, "prob": 30, "riesgoPais": 300, "senales": ["Brecha CCL-oficial por encima de 15%", "Reservas brutas por debajo de u$s48.000 millones"], "spx": -2, "tasas": 25}, {"descripcion": "Un PCE moderado y señales oficiales de financiamiento para los vencimientos de 2027 llevan el riesgo país de nuevo hacia 850 pb, como tras el rebote de mediados de noviembre. El BCRA retoma compras con la cosecha fina.", "dolar": 1, "id": "alivio-rebote", "nombre": "Alivio y rebote", "petroleo": -5, "prob": 15, "riesgoPais": -250, "senales": ["Anuncio de financiamiento externo o con organismos para 2027", "Riesgo país de vuelta por debajo de 950 pb"], "spx": 4, "tasas": 15}, {"descripcion": "Un PCE alto lleva a la Fed a subir 50 pb o a señalar más subas, y las tecnológicas profundizan la corrección con el S&P 500 cayendo bajo 7.000 puntos desde 7.201. Los emergentes sufren la salida de fondos.", "dolar": 4, "id": "fed-dura-ia", "nombre": "Fed dura y caída de la IA", "petroleo": -5, "prob": 12, "riesgoPais": 150, "senales": ["Probabilidad de suba de 50 pb en diciembre por encima de 30%", "S&P 500 cerrando por debajo de 7.000 puntos"], "spx": -8, "tasas": 50}, {"descripcion": "Se rompen las negociaciones entre EE.UU. e Irán y vuelven los ataques: el Brent pasa de US$91 a más de US$105. Favorece a energéticas locales, pero la aversión global al riesgo pesa sobre bonos y Cedears.", "dolar": 3, "id": "escalada-ormuz", "nombre": "Escalada en Ormuz", "petroleo": 20, "prob": 8, "riesgoPais": 100, "senales": ["Brent por encima de US$100", "Nuevos ataques a petroleros o fin de la tregua anunciada por Trump"], "spx": -5, "tasas": 10}]'::jsonb, '[{"portal": "Perfil", "url": "https://www.perfil.com/economia/el-riesgo-pais-rompe-la-barrera-de-los-1100-puntos-y-alcanza-el-nivel-mas-alto-del-ano-mientras-el-dolar-oficial-llega-a-1615-a5Q7B3m4Fz5t"}, {"portal": "El Cronista", "url": "https://www.cronista.com/finanzas-mercados/dolar-blue-hoy-a-cuanto-cotiza-este-martes-24-de-noviembre-con-el-mep-y-el-ccl/"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/el-bcra-no-compro-dolares-segunda-rueda-fila-y-las-reservas-cayeron-al-menor-nivel-mas-un-mes-n6348885"}, {"portal": "Ámbito", "url": "https://www.ambito.com/la-economia-entro-recesion-tecnica-sumo-dos-trimestres-seguidos-caida-pese-crecer-11-mensual-septiembre-n6348824"}, {"portal": "Ámbito", "url": "https://www.ambito.com/uruguay/el-dolar-global-retrocede-y-wall-street-vuelve-caer-desinflarse-el-repunte-nvidia-n6348521"}, {"portal": "StockTitan", "url": "https://www.stocktitan.net/articles/stock-market-today-live-november-24-2026"}, {"portal": "Bloomberg (vía Rigzone)", "url": "https://www.rigzone.com/news/wire/oil_climbs_despite_growing_oversupply_fears-24-nov-2026-185160-article/"}]'::jsonb),
  ('2026-11-26', '2026-11-26T08:50:00-03:00', 'Los activos argentinos vienen de una semana muy dura: el riesgo país llegó a tocar 1.134 puntos el miércoles y el dólar mayorista marcó un récord de $1.604, en medio de la recesión técnica y un BCRA que dejó de comprar dólares. Caputo salió a calmar con el pedido de US$5.000 millones del swap chino y un plan para pagar los US$4.400 millones de enero, y el riesgo país cerró en 1.068, pero afuera la Fed se encamina a subir tasas y Trump suma aranceles. El dato a mirar hoy es si el riesgo país se sostiene por debajo de 1.100 y si el BCRA vuelve a comprar dólares, con Wall Street cerrado por Acción de Gracias.', '{"explicacion": "Lo local pesa más: recesión técnica, dólar en récord, BCRA sin compras y dudas sobre el financiamiento 2027, apenas compensados por el anuncio del swap chino y el plan de pagos de enero. Afuera, la inflación PCE de 3,8% casi asegura una suba de la Fed en diciembre y los nuevos aranceles de EE.UU. suman ruido; el rebote de Brasil y el cierre casi plano de Wall Street amortiguan algo. No es la suma de los ítems: el salto del riesgo país y el del dólar reflejan en parte las mismas causas.", "factorAR": -0.4, "factorGlobal": -0.25}'::jsonb, '[{"ajustes": {"soberanos": -0.03}, "ambito": "Argentina", "canal": "Bonos soberanos más baratos implican pérdidas en papel y encarecen el refinanciamiento de 2027, lo que contagia a ONs y acciones.", "confianza": "alta", "factorAR": -0.25, "factorGlobal": 0, "fuente": "Perfil", "horizonte": "semanas", "id": "riesgo-pais-maximo-14-meses", "resumen": "El riesgo país llegó a 1.134 pb el miércoles 25 (máximo en 14 meses), sube 44,1% en noviembre y 98,6% desde enero; el GD41 cae cerca de 10% en el mes. Según Rava, terminó cerrando en 1.068 pb (-2,4%) tras un rebote en la tarde.", "titulo": "El riesgo país tocó 1.134 puntos, su nivel más alto en 14 meses, y acumula +44% en noviembre", "url": "https://perfil.com/economia/el-riesgo-pais-escala-a-1.139-puntos-y-toca-su-nivel-mas-alto-en-14-meses-aV6fv1g34pm4"}, {"ajustes": {"cer": -0.02, "pesos": -0.04}, "ambito": "Argentina", "canal": "Una devaluación más rápida licúa las posiciones en pesos y CER medidas en dólares y reduce el colchón del BCRA para el año electoral.", "confianza": "alta", "factorAR": -0.3, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "dolar-record-bcra-sin-compras", "resumen": "El mayorista subió por séptima rueda seguida a $1.604 y el BCRA no compró por tercera vez; las reservas quedaron en US$48.748 millones tras caer US$618 millones el martes. El CCL cerró en $1.780 (brecha de 11%) y el blue superó por primera vez los $1.700.", "titulo": "Dólar mayorista en récord de $1.604 y BCRA tres ruedas sin comprar; reservas en US$48.748 millones", "url": "https://www.ambito.com/finanzas/en-medio-la-tension-cambiaria-el-bcra-dejo-las-compras-pausa-tecera-rueda-consecutiva-n6349347"}, {"ajustes": {"soberanos": 0.03}, "ambito": "Argentina", "canal": "Reduce el temor a un incumplimiento cercano y puede comprimir el riesgo país, aunque el pago sale de reservas del BCRA.", "confianza": "media", "factorAR": 0.3, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "caputo-swap-china-pago-enero", "resumen": "Para los ~US$4.400 millones de enero, el Tesoro usará US$1.200 millones de FMI y multilaterales, US$1.000 millones de créditos garantizados por CAF/Fonplata, US$300 millones de AySA y le comprará US$1.800 millones al BCRA. El pedido del swap chino busca reemplazar los US$5.000 millones en Bonares que no se pudieron colocar para 2027.", "titulo": "Caputo pidió a China activar US$5.000 millones del swap y detalló cómo pagará los vencimientos de enero", "url": "https://www.ambito.com/finanzas/luis-caputo-revelo-que-pidio-china-usar-una-parte-del-swap-y-detallo-como-pagara-la-deuda-enero-n6349364"}, {"ajustes": {"merval": -0.02}, "ambito": "Argentina", "canal": "Menos actividad pega en ganancias de bancos y empresas locales y alimenta las dudas políticas de cara a 2027.", "confianza": "alta", "factorAR": -0.2, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "meses", "id": "recesion-tecnica-emae", "resumen": "La actividad creció 1,1% mensual en septiembre pero cayó 1,2% interanual; el tercer trimestre se contrajo 1,8% tras -0,6% en el segundo. El REM espera solo 0,7% de crecimiento en 2026 y el PBI oficial se conocerá el 16 de diciembre.", "titulo": "El EMAE de septiembre confirmó recesión técnica: -1,8% en el tercer trimestre pese al rebote mensual", "url": "https://www.ambito.com/la-economia-entro-recesion-tecnica-sumo-dos-trimestres-seguidos-caida-pese-crecer-11-mensual-septiembre-n6348824"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. presionan las valuaciones de acciones y restan atractivo a la deuda emergente como la argentina.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.3, "fuente": "ABC News", "horizonte": "semanas", "id": "pce-fed-suba-diciembre", "resumen": "La PCE de octubre pasó de 3,6% a 3,8% anual y el FedWatch de CME asigna cerca de 97% a una suba de 0,25 puntos en diciembre. Sería la segunda suba en cuatro meses bajo la presidencia de Kevin Warsh.", "titulo": "La inflación PCE subió a 3,8% y el mercado da por hecha una suba de tasas de la Fed el 8-9 de diciembre", "url": "https://abcnews.com/Business/inflation-report-provide-feds-preferred-gauge-prices-ahead/story?id=138410424"}, {"ajustes": {"cedears": -0.02}, "ambito": "Mundo", "canal": "Más guerra comercial golpea las bolsas globales, los Cedears y a Brasil, principal socio comercial de Argentina.", "confianza": "media", "factorAR": -0.1, "factorGlobal": -0.25, "fuente": "AP (ABC News)", "horizonte": "meses", "id": "aranceles-eeuu-china-ue-brasil", "resumen": "La administración Trump propone un 20% adicional a bienes chinos (hasta 45% en algunos) y nuevas tasas a la UE y otros 12 países; Brasil recibe castigo extra con aranceles al azúcar y 10% a aviones. Las bolsas llegaron a caer más de 3% en la mañana del miércoles antes de recuperarse: el S&P 500 cerró en 7.182,78 (-0,25%).", "titulo": "EE.UU. planea subir aranceles a China (+20%), la UE, Japón y Brasil, entre otros", "url": "https://abcnews.com/US/wireStory/us-plans-hike-tariffs-china-eu-brazil-subsidized-138438618"}, {"ajustes": {"merval": 0.02, "ons": 0.02}, "ambito": "Mundo", "canal": "Petróleo más caro ayuda a energéticas argentinas (YPF, Vista) pero suma inflación global y presión sobre la Fed.", "confianza": "media", "factorAR": 0.05, "factorGlobal": -0.15, "fuente": "The Nation (con datos de Reuters)", "horizonte": "días", "id": "brent-ataque-huti-ras-tanura", "resumen": "El Brent cerró en US$94,61 (+3,5%) y el WTI en US$83,68 (+2%) luego de que los hutíes dijeran haber atacado Ras Tanura. La OPEP+ se reúne el 29 de noviembre para definir cuotas 2027, con temor a un exceso de oferta.", "titulo": "El Brent saltó 3,5% a US$94,61 tras el ataque hutí a la refinería saudí de Ras Tanura", "url": "https://www.nationthailand.com/news/world/40073934"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Un real más firme alivia el contagio regional y la presión competitiva sobre el peso argentino.", "confianza": "baja", "factorAR": 0.1, "factorGlobal": 0.05, "fuente": "The Rio Times", "horizonte": "días", "id": "brasil-rebote-real-ibovespa", "resumen": "El Ibovespa cerró en 166.685 (+1,58%) y el dólar bajó 1,39% a 5,8245 reales, tercera caída seguida. Aun así, la bolsa sigue 20,3% debajo de su pico de octubre.", "titulo": "Brasil rebotó: el Ibovespa subió 1,58% y el dólar cayó a 5,82 reales", "url": "https://www.riotimesonline.com/brazil-markets-ibovespa-real-wednesday-november-25-2026/"}]'::jsonb, '[{"descripcion": "China fondea los US$5.000 millones del swap y el directorio del FMI aprueba la revisión (~US$900 millones), el BCRA vuelve a comprar y el riesgo país baja desde 1.068 hacia la zona de 800. El dólar mayorista se estabiliza cerca de $1.600-1.650.", "dolar": 3, "id": "swap-y-fmi-calman", "nombre": "Swap y FMI calman", "petroleo": -5, "prob": 25, "riesgoPais": -250, "senales": ["Confirmación oficial de China sobre el desembolso del swap", "El BCRA retoma compras diarias y las reservas superan US$49.000 millones"], "spx": 3, "tasas": 0}, {"descripcion": "El mercado no compra del todo el plan de Caputo: el riesgo país oscila entre 1.000 y 1.150 y el dólar sigue subiendo de a poco desde $1.604. La Fed sube 0,25 puntos en diciembre, como ya está descontado.", "dolar": 6, "id": "tension-que-se-estira", "nombre": "Tensión que se estira", "petroleo": 0, "prob": 35, "riesgoPais": 50, "senales": ["El CCL se mantiene arriba de $1.750 con brecha de dos dígitos", "El riesgo país no logra perforar los 1.000 puntos en diciembre"], "spx": -2, "tasas": 15}, {"descripcion": "La recesión y la caída de reservas desatan una corrida: el riesgo país supera los 1.400 puntos y el mayorista salta muy por encima de $1.800. Se reabren dudas sobre la continuidad del equipo económico y el pago de enero.", "dolar": 18, "id": "estres-local-salto-cambiario", "nombre": "Estrés local y salto del dólar", "petroleo": 0, "prob": 15, "riesgoPais": 400, "senales": ["Reservas brutas por debajo de US$47.000 millones", "Licitaciones del Tesoro con rollover bajo 90% y tasas en pesos en alza fuerte"], "spx": -3, "tasas": 20}, {"descripcion": "La Fed sube 0,50 puntos o anticipa más subas en enero mientras EE.UU. aplica los nuevos aranceles; el S&P 500 vuelve a caer desde 7.182 y los emergentes sufren salida de capitales. Argentina recibe el golpe amplificado.", "dolar": 8, "id": "fed-dura-y-aranceles", "nombre": "Fed dura y guerra comercial", "petroleo": -8, "prob": 15, "riesgoPais": 150, "senales": ["Waller u otros miembros de la Fed votan por 0,50 puntos el 9 de diciembre", "El rendimiento del Treasury a 10 años supera 5%"], "spx": -8, "tasas": 40}, {"descripcion": "Los ataques en Ras Tanura y Ormuz cortan oferta real y el Brent pasa de US$94,61 a más de US$110, reavivando la inflación global. Las energéticas argentinas se benefician, pero el resto del mercado sufre la suba de tasas.", "dolar": 5, "id": "shock-petrolero-golfo", "nombre": "Shock petrolero en el Golfo", "petroleo": 20, "prob": 10, "riesgoPais": 50, "senales": ["Aramco confirma daño o cierre en Ras Tanura", "La OPEP+ no acuerda cuotas el 29 de noviembre y el Brent supera US$100"], "spx": -5, "tasas": 25}]'::jsonb, '[{"portal": "Perfil", "url": "https://perfil.com/economia/el-riesgo-pais-escala-a-1.139-puntos-y-toca-su-nivel-mas-alto-en-14-meses-aV6fv1g34pm4"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/en-medio-la-tension-cambiaria-el-bcra-dejo-las-compras-pausa-tecera-rueda-consecutiva-n6349347"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/luis-caputo-revelo-que-pidio-china-usar-una-parte-del-swap-y-detallo-como-pagara-la-deuda-enero-n6349364"}, {"portal": "Ámbito", "url": "https://www.ambito.com/la-economia-entro-recesion-tecnica-sumo-dos-trimestres-seguidos-caida-pese-crecer-11-mensual-septiembre-n6348824"}, {"portal": "ABC News", "url": "https://abcnews.com/Business/inflation-report-provide-feds-preferred-gauge-prices-ahead/story?id=138410424"}, {"portal": "AP (ABC News)", "url": "https://abcnews.com/US/wireStory/us-plans-hike-tariffs-china-eu-brazil-subsidized-138438618"}, {"portal": "The Nation (con datos de Reuters)", "url": "https://www.nationthailand.com/news/world/40073934"}, {"portal": "The Rio Times", "url": "https://www.riotimesonline.com/brazil-markets-ibovespa-real-wednesday-november-25-2026/"}]'::jsonb),
  ('2026-11-27', '2026-11-27T08:50:00-03:00', 'Los activos argentinos respiraron el jueves: los bonos subieron cerca de 2% con la media sanción para suspender las PASO, el plan de Caputo para pagar enero y el salto de Brasil, aunque el riesgo país sigue en 1.067 puntos y el Central lleva cuatro ruedas sin comprar dólares. Afuera el clima es más pesado, porque la inflación de EE.UU. dejó casi segura una suba de tasas de la Fed en diciembre y el petróleo volvió a subir por los ataques en el Golfo. Hoy hay que mirar si el riesgo país, que vuelve a cotizar en Nueva York en una rueda corta, confirma el rebote y perfora los 1.000 puntos.', '{"explicacion": "Lo local suma un alivio moderado (señal política, financiamiento de enero y viento de Brasil), pero buena parte ya se vio en el rebote del jueves y persiste la duda por reservas. Lo global resta: Fed que sube tasas, nuevos aranceles y petróleo en alza pesan sobre bolsas y emergentes; se cuentan una sola vez aunque aparezcan en varias notas.", "factorAR": 0.15, "factorGlobal": -0.3}'::jsonb, '[{"ajustes": {}, "ambito": "Argentina", "canal": "Menos ruido electoral comprime el riesgo país y mejora el precio de soberanos y acciones locales en dólares.", "confianza": "media", "factorAR": 0.3, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "semanas", "id": "paso-bonos-rebote", "resumen": "El Senado dio media sanción a la suspensión de las PASO; el AL30 fue el más buscado y su rendimiento bajó de 19% a 18%. El Tesoro renovó $25,4 billones, adjudicó $26,71 billones y absorbió $1,3 billones con tasas de 2,2% a 2,5% mensual.", "titulo": "Bonos suben hasta 2% tras la media sanción para suspender las PASO; riesgo país en 1.067", "url": "https://www.infobae.com/economia/2026/11/27/la-politica-inclino-la-balanza-los-activos-argentinos-repuntaron-tras-la-media-sancion-del-proyecto-para-suspender-las-paso/"}, {"ajustes": {"mep": 0.03, "pesos": -0.05}, "ambito": "Argentina", "canal": "Sin compras del BCRA crece la presión cambiaria y la demanda de cobertura, lo que pesa sobre activos en pesos.", "confianza": "media", "factorAR": -0.25, "factorGlobal": 0, "fuente": "Ámbito", "horizonte": "semanas", "id": "bcra-sin-compras-brecha", "resumen": "El mayorista cerró en $1.601, el MEP en $1.670,82 y el CCL en $1.832,86, con brecha de 14,5%. El Central no compra divisas hace cuatro ruedas, la pausa más larga del año, y las reservas bajaron USD 15 millones.", "titulo": "El BCRA encadena cuatro ruedas sin comprar dólares y la brecha con el CCL ronda el 14%", "url": "https://www.ambito.com/finanzas/dolar-blue-hoy-cuanto-opera-este-jueves-26-noviembre-n6349465"}, {"ajustes": {"soberanos": 0.03}, "ambito": "Argentina", "canal": "Despeja el riesgo de pago inmediato y sostiene a los soberanos, aunque consume reservas para intervenir en el año electoral.", "confianza": "media", "factorAR": 0.15, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "semanas", "id": "caputo-vencimiento-enero", "resumen": "El Tesoro reunirá USD 2.600 millones de organismos, CAF/Fonplata y la venta de AySA, y comprará USD 1.800 millones al BCRA; además pidió activar USD 5.000 millones del swap con China. El mercado duda porque resta poder de fuego al Central.", "titulo": "Caputo detalla cómo pagará los USD 4.370 millones de enero: multilaterales, AySA y compra al BCRA", "url": "https://www.infobae.com/economia/2026/11/27/el-plan-de-caputo-para-pagar-el-abultado-vencimiento-deuda-de-enero-que-efecto-tendra-sobre-las-reservas-del-central/"}, {"ajustes": {}, "ambito": "Argentina", "canal": "Mejora la credibilidad institucional de largo plazo, con efecto gradual sobre riesgo país y tasas en pesos.", "confianza": "media", "factorAR": 0.1, "factorGlobal": 0, "fuente": "Infobae", "horizonte": "meses", "id": "carta-organica-bcra-ley", "resumen": "Diputados aceptó los cambios del Senado: el BCRA tendrá mandato único de preservar el valor de la moneda, no podrá financiar al Estado y su directorio tendrá mandatos de seis años con acuerdo del Senado.", "titulo": "Es ley la reforma de la Carta Orgánica del BCRA: se terminan los adelantos al Tesoro", "url": "https://www.infobae.com/economia/2026/11/26/seis-claves-para-entender-la-nueva-ley-que-reforma-la-carta-organica-del-banco-central/"}, {"ajustes": {"cedears": -0.03}, "ambito": "Mundo", "canal": "Tasas más altas en EE.UU. encarecen el financiamiento emergente y presionan a CEDEARs tecnológicos.", "confianza": "alta", "factorAR": -0.1, "factorGlobal": -0.35, "fuente": "Yahoo Finance", "horizonte": "semanas", "id": "pce-fed-suba-aranceles", "resumen": "La inflación PCE de octubre subió a 3,8% anual y la núcleo a 3,3% (se esperaba 3,2%); EE.UU. propuso aranceles de hasta 20% a China, la UE y 12 países. El S&P 500 cerró en 7.182,78 (-0,25%) y el Nasdaq cayó 0,62%, con el bono a 10 años en 4,85%.", "titulo": "PCE de EE.UU. en 3,8% y núcleo 3,3%: el mercado da 98% de chances a una suba de la Fed", "url": "https://finance.yahoo.com/markets/live/stock-market-today-wednesday-november-25-dow-sp-500-nasdaq-pce-inflation-data-091428237.html"}, {"ajustes": {"merval": 0.04}, "ambito": "Mundo", "canal": "Petróleo más caro favorece a energéticas locales como YPF pero suma inflación y aversión al riesgo global.", "confianza": "media", "factorAR": 0, "factorGlobal": -0.15, "fuente": "The Nation (Thailand)", "horizonte": "días", "id": "brent-ormuz-opep", "resumen": "El Brent cerró en US$96,57 (+2,07%) el 26/11 tras reportes de dos petroleros que chocaron minas en Ormuz y un ataque hutí a Ras Tanura. La OPEP+ se reúne el 29/11 y probablemente mantenga cuotas hasta marzo de 2027.", "titulo": "Brent sube 2% a US$96,57 por minas en Ormuz y ataque a refinería saudí; OPEP+ se reúne el domingo", "url": "https://www.nationthailand.com/news/world/40073981"}, {"ajustes": {}, "ambito": "Mundo", "canal": "Un real más firme alivia la presión sobre el peso y mejora el apetito por activos de la región.", "confianza": "media", "factorAR": 0.15, "factorGlobal": 0.05, "fuente": "El Cronista", "horizonte": "semanas", "id": "brasil-trabuco-bovespa", "resumen": "El Ibovespa subió 6,07% a 176.799 puntos y el real se apreció 1,25% a 5,744 por dólar, ayudado además por una inflación previa de noviembre de 0,22%.", "titulo": "Lula elige a Trabuco (Bradesco) para Hacienda: el Ibovespa salta 6,07% y el real se aprecia", "url": "https://www.cronista.com/internacionales/lula-designo-a-un-hombre-de-bradesco-como-ministro-de-economia-quien-es-y-cual-es-la-senal-fiscal-que-celebraron-los-mercados/"}]'::jsonb, '[{"descripcion": "El rebote post-PASO se consolida, el riesgo país vuelve por debajo de 900 desde 1.067 y el BCRA retoma compras con reservas sobre USD 49.000 millones.", "dolar": 2, "id": "alivio-sostenido", "nombre": "Alivio sostenido", "petroleo": -5, "prob": 25, "riesgoPais": -200, "senales": ["Riesgo país por debajo de 1.000 puntos al cierre de la semana", "El BCRA vuelve a comprar dólares en el MLC"], "spx": 4, "tasas": -10}, {"descripcion": "Los activos se estabilizan con riesgo país entre 950 y 1.100 y un mayorista que sigue subiendo cerca de 4% mensual, lejos del techo de banda de $1.984.", "dolar": 4, "id": "meseta-tensa", "nombre": "Meseta tensa", "petroleo": 0, "prob": 35, "riesgoPais": -50, "senales": ["Brecha MEP-oficial estable en torno a 3-5%", "Licitaciones del Tesoro con rollover cerca de 100%"], "spx": 0, "tasas": 15}, {"descripcion": "La Fed sube tasas el 9/12 y anticipa más, con el bono a 10 años sobre 5% desde 4,85% y los aranceles de 20% confirmados; emergentes y tecnológicas caen.", "dolar": 5, "id": "fed-halcon-aranceles", "nombre": "Fed halcón y aranceles", "petroleo": 3, "prob": 20, "riesgoPais": 100, "senales": ["Rendimiento del Treasury a 10 años arriba de 5%", "VIX nuevamente sobre 30"], "spx": -8, "tasas": 40}, {"descripcion": "Sin compras del BCRA y con el pago de enero consumiendo reservas, la demanda de cobertura empuja el dólar hacia el techo de la banda y el riesgo país supera 1.300.", "dolar": 15, "id": "estres-cambiario-local", "nombre": "Estrés cambiario local", "petroleo": 0, "prob": 12, "riesgoPais": 350, "senales": ["Reservas brutas por debajo de USD 47.000 millones", "CCL con brecha mayor a 20% sobre el mayorista"], "spx": -2, "tasas": 10}, {"descripcion": "Nuevos ataques cortan flujos por Ormuz y el Brent pasa de US$96,57 a más de US$115, sumando inflación global y aversión al riesgo.", "dolar": 4, "id": "shock-petrolero-ormuz", "nombre": "Shock petrolero en Ormuz", "petroleo": 20, "prob": 8, "riesgoPais": 80, "senales": ["Brent sostenido arriba de US$105", "Caída de exportaciones del Golfo informada por la OPEP+ o la AIE"], "spx": -6, "tasas": 20}]'::jsonb, '[{"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/27/la-politica-inclino-la-balanza-los-activos-argentinos-repuntaron-tras-la-media-sancion-del-proyecto-para-suspender-las-paso/"}, {"portal": "Ámbito", "url": "https://www.ambito.com/finanzas/dolar-blue-hoy-cuanto-opera-este-jueves-26-noviembre-n6349465"}, {"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/27/el-plan-de-caputo-para-pagar-el-abultado-vencimiento-deuda-de-enero-que-efecto-tendra-sobre-las-reservas-del-central/"}, {"portal": "Infobae", "url": "https://www.infobae.com/economia/2026/11/26/seis-claves-para-entender-la-nueva-ley-que-reforma-la-carta-organica-del-banco-central/"}, {"portal": "Yahoo Finance", "url": "https://finance.yahoo.com/markets/live/stock-market-today-wednesday-november-25-dow-sp-500-nasdaq-pce-inflation-data-091428237.html"}, {"portal": "The Nation (Thailand)", "url": "https://www.nationthailand.com/news/world/40073981"}, {"portal": "El Cronista", "url": "https://www.cronista.com/internacionales/lula-designo-a-un-hombre-de-bradesco-como-ministro-de-economia-quien-es-y-cual-es-la-senal-fiscal-que-celebraron-los-mercados/"}]'::jsonb)
